# Stories for albums 301–350 (long format agreed with the owner: three paragraphs + a listening tip,
# ~200–250 words, three picks). Original Hebrew; facts checked on the web, uncertain ones softened.
# Used by tools/batches/build_301_350.py; later edits: python3 tools/apply_stories.py stories_301_350
STORIES = {}
def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(301, [
'''באד קומפני נולדה ב־1973 כ"להקת־על" קטנה: הזמר פול רוג׳רס והמתופף סיימון קירק הגיעו מלהקת Free, הגיטריסט מיק ראלפס עזב את מוט דה הופל (אלבום 285), והבסיסט בוז בורל ניגן קודם בקינג קרימזון. הם היו הלהקה הראשונה שהוחתמה בחברת התקליטים החדשה של לד זפלין, והמנהל שלהם היה המנהל החזק של זפלין עצמם. את אלבום הבכורה הקליטו בבית כפרי ישן באנגליה, עם אולפן נייד.''',
'''זה רוק פשוט, בלי קישוטים: גיטרה עבה, תופים כבדים ואיטיים, והרבה אוויר בין הכלים. מעל הכול עומד הקול של רוג׳רס, חם, מחוספס ומלא נשמה, אחד הקולות הגדולים של הרוק הבריטי. Can’t Get Enough פותח בריף שכל נער עם גיטרה למד לנגן, השיר Bad Company הוא בלדה אפלה על פורעי חוק במערב הפרוע, ו־Seagull שסוגר את האלבום הוא שיר אקוסטי ושקט. הנגינה של ראלפס פשוטה ומדויקת: הוא לא מנסה להרשים, אלא לשרת את השיר, ומשאיר לקירק ולבורל מקום לנשום.''',
'''האלבום הגיע למקום הראשון באמריקה, ושיריו מתנגנים ברדיו הרוק עד היום. הוא קבע נוסחה שרבות מלהקות הרוק של אמצע שנות השבעים הלכו בה: פחות סולואים ארוכים ויותר שירים חזקים, עם פזמון שנכנס לראש. רוג׳רס וקירק כבר ניגנו יחד את All Right Now עם Free, ובבאד קומפני הם לקחו את אותה פשטות והפכו אותה לנוסחה של אצטדיונים.''',
'''שימו לב לשקט: באד קומפני יודעים מתי לא לנגן, ולכן כל ריף נשמע גדול. את Ready for Love כתב ראלפס עוד בתקופת מוט דה הופל, ואם תשוו לגרסה שלהם תשמעו כמה הקול של רוג׳רס משנה שיר.''',
], [
('Can’t Get Enough', 'הלהיט הגדול: ריף פשוט ומושלם ושירה מלאת ביטחון, שיר שכל להקת רוק צעירה למדה לנגן.'),
('Bad Company', 'שיר הנושא: פסנתר אפל, תופים איטיים וסיפור על שודדים במערב הפרוע, כמו סצנה ממערבון.'),
('Seagull', 'רוג׳רס לבד עם גיטרה אקוסטית, סיום שקט ויפה על שחף שעף מעל הים.'),
])

add(302, [
'''זה האלבום האחרון של ג׳נסיס עם הזמר פיטר גבריאל, ואולי השאפתני שבהם. ב־1974 הלהקה הקליטה אלבום כפול שמספר סיפור אחד: רֵאֵל, נער פורטוריקני מרחובות ניו יורק, נבלע בענן מסתורי בברודווי ויורד לעולם תת־קרקעי ומוזר, מלא יצורים, חדרים וסמלים, עד שהוא נאלץ להציל את אחיו. גבריאל כתב כמעט את כל המילים, ושאר חברי הלהקה כתבו את רוב המוזיקה, והמתח ביניהם הורגש לאורך כל העבודה.''',
'''המוזיקה שונה מהאלבומים הקודמים של ג׳נסיס: פחות אנגלית וכפרית, יותר עירונית וחדה. יש שירי רוק קצרים וקצביים, קטעי אווירה שקטים ומוזרים, ובלדות יפות במיוחד כמו The Carpet Crawlers. הקלידים של טוני בנקס מציירים נופים שלמים, והגיטרה של סטיב האקט מוסיפה צבעים עדינים. בריאן אינו (אלבום 300) עזר בעיבוד הקול של גבריאל בכמה קטעים. יש גם רגעים משונים ומצחיקים, כמו השיר על היצורים שנקראים "אנשי החלקלקות", ורגעים של רעש ואווירה שבהם כמעט אין מלודיה.''',
'''בסיבוב ההופעות גבריאל הופיע בתחפושות מופלאות, ואחריו עזב את הלהקה. המתופף פיל קולינס הפך לזמר, וג׳נסיס פנתה בהדרגה לפופ והפכה לאחת הלהקות המצליחות בעולם. האלבום עצמו נחשב לאחת פסגות הרוק המתקדם, ולסיפור שמעריצים מפענחים עד היום. הקהל בהופעות שמע את כל היצירה ברצף, לפני שרוב האנשים הכירו את השירים, וגבריאל הקרין שקופיות מאחור כדי לעזור לו לעקוב אחרי הסיפור.''',
'''אל תנסו להבין את כל העלילה בשמיעה ראשונה, גם המעריצים לא הבינו. תנו למוזיקה להוביל, ואם אהבתם את Selling England by the Pound (אלבום 279), שימו לב כמה הלהקה השתנתה בשנה אחת.''',
], [
('The Lamb Lies Down on Broadway', 'הפתיחה: פסנתר מתגלגל, ורֵאֵל יוצא לרחובות ניו יורק בבוקר שבו הכול עומד להשתנות.'),
('The Carpet Crawlers', 'אחד השירים היפים של ג׳נסיס: מנגינה חוזרת ועולה, כמו טיפוס איטי במדרגות אל האור.'),
('In the Cage', 'רֵאֵל כלוא בכלוב של נטיפים: קלידים מהירים, תופים דחופים ומתח שהולך וגדל.'),
])

add(303, [
'''שוגי אוטיס היה בנו של ג׳וני אוטיס, מראשוני הרית׳ם אנד בלוז, והיה גיטריסט מחונן כבר בגיל צעיר מאוד. בתחילת שנות השבעים הוא הסתגר באולפן ועבד כשלוש שנים על אלבום שבו ניגן בעצמו כמעט על כל הכלים: גיטרות, בס, קלידים ותופים, ולצידם מכונת תופים פשוטה, דבר נדיר מאוד באותם ימים. האלבום יצא ב־1974 ונכשל: הוא כמעט לא נמכר, וחברת התקליטים נפרדה ממנו. אוטיס כמעט לא הוציא אלבומים חדשים במשך עשרות שנים. לפי סיפורים רבים, הוא אף קיבל הצעה להצטרף לרולינג סטונס, ודחה אותה כי העדיף לעבוד על המוזיקה שלו.''',
'''המוזיקה נשמעת כמו חלום בצהרי יום חם: סול ופאנק רכים, גיטרות עם הדים, אורגן חם, קצב מכונה עדין וקול שקט ומלטף. Inspiration Information פותח בפזמון שמח וקליל, Island Letter הוא בלדה חלומית, ו־Aht Uh Mi Hed הוא שיר רך ומתנדנד. בצד השני יש קטעים אינסטרומנטליים שנשמעים כאילו הוקלטו בחדר שינה, הרבה לפני שזה היה נפוץ. גם הגיטרה שלו לא נשמעת כמו גיטרה של כוכב רוק, אלא כמו קול נוסף, רך ומתפתל, שמשוחח עם הקלידים.''',
'''ב־2001 האלבום יצא מחדש בחברה של דייוויד ביירן, וקהל חדש גילה אותו. היום הוא נחשב לאוצר אבוד של הסול, והשפיע על מוזיקאים שעובדים לבד באולפן ביתי. שיר קודם של אוטיס, Strawberry Letter 23, הפך ללהיט כשלהקה אחרת הקליטה אותו.''',
'''זה אלבום לשעות הערב, לנסיעה או לבישול. אם אהבתם את הסול החם של There’s a Riot Goin’ On (אלבום 206), שגם בו יש מכונת תופים וקול עמום, תשמעו כאן קרבה.''',
], [
('Inspiration Information', 'שיר הנושא: פזמון קליל, כלי נשיפה ותחושת קיץ, כמו אחר צהריים חם בקליפורניה.'),
('Island Letter', 'בלדה חלומית ורכה, כמו מכתב מאי רחוק, עם גיטרה מהדהדת וקול לוחש.'),
('Aht Uh Mi Hed', 'שיר מתנדנד ועדין עם גיטרה חמה וקצב מכונה, מהשירים האהובים של אוטיס.'),
])

add(304, [
'''באוגוסט 1973, זמן קצר אחרי יציאת Innervisions (אלבום 292), סטיבי וונדר נפצע קשה בתאונת דרכים ושכב כמה ימים מחוסר הכרה. הוא החלים, אבל משהו השתנה: האלבום הבא, שיצא ב־1974, רציני, רוחני ומלא מחשבות על החיים ועל המוות. גם הפעם וונדר ניגן בעצמו על רוב הכלים, והמשיך בסדרת האלבומים המדהימה שלו מתחילת שנות השבעים.''',
'''יש כאן כמה פנים: You Haven’t Done Nothin’ הוא שיר פאנק זועם נגד פוליטיקאים שמבטיחים ולא עושים, עם קולות רקע של להקת ג׳קסון 5, ונשמע כמו תשובה ישירה לנשיא ניקסון, שהתפטר באותו קיץ. Boogie On Reggae Woman הוא שיר שובב ומקפץ, עם סינתיסייזר בס עגול ומפוחית. ובין לבין יש בלדות שקטות ועמוקות, כמו They Won’t Go When I Go, שיר כמעט דתי על מה שיישאר אחרינו. לאורך האלבום וונדר חוזר שוב ושוב לאמונה, לאהבה ולתקווה, אבל בלי להטיף: יותר כמו אדם שמדבר עם עצמו אחרי שחזר מסכנה.''',
'''האלבום הגיע למקום הראשון במצעד וזכה בפרס הגראמי לאלבום השנה, השני ברציפות של וונדר. הוא אולי פחות מפורסם מקודמיו, אבל רבים אוהבים אותו דווקא בגלל השקט והעומק שבו. אחרי האלבום הזה הוא לקח שנתיים והוציא את Songs in the Key of Life, אלבום כפול שהפך לאחד המפורסמים שלו.''',
'''שמעו אותו אחרי Talking Book (אלבום 255) ו־Innervisions, ותרגישו איך אותו אמן עובר ממצב רוח של אהבה, דרך כעס חברתי, אל הרהור על החיים.''',
], [
('Boogie On Reggae Woman', 'שובב ומקפץ: סינתיסייזר בס עגול, מפוחית וחיוך גדול, מהשירים השמחים של וונדר.'),
('You Haven’t Done Nothin’', 'שיר מחאה פאנקי וזועם נגד פוליטיקאים שלא עושים כלום, עם קולות הרקע של הג׳קסון 5.'),
('They Won’t Go When I Go', 'בלדה שקטה וכמעט דתית על מה שנשאר אחרינו, מהרגעים העמוקים של וונדר.'),
])

add(305, [
'''אחרי Layla (אלבום 175) אריק קלפטון נעלם לשלוש שנים: הוא היה מכור להרואין, כמעט לא הופיע ולא הקליט. ב־1974, אחרי גמילה, הוא טס למיאמי, גר בבית ברחוב Ocean Boulevard מספר 461 (ומכאן שם האלבום), והקליט עם להקה חדשה ורגועה. זה היה אלבום הקאמבק שלו, והוא הגיע למקום הראשון באמריקה.''',
'''הסאונד רך ונינוח, כמעט של חופשה: בלוז, רוק רגוע ונגיעות של גוספל וקאנטרי, עם קולות נשיים ברקע, בעיקר של הזמרת איבון אלימן. קלפטון כמעט לא מנגן כאן סולואים ארוכים וסוערים, אלא שר יותר, בשקט ובחום. יש שירי בלוז ישנים שקיבלו לבוש חדש, כמו Motherless Children, ושירים שכתב בעצמו, כמו Let It Grow, אחד היפים שלו. הגיטרה של קלפטון נשמעת כאן פחות כמו כלי של גיבור ויותר כמו חבר נוסף בלהקה, והקולות הנשיים מוסיפים חום של כנסייה דרומית.''',
'''הלהיט הגדול היה I Shot the Sheriff, גרסה לשיר של בוב מארלי מאלבום של הוויילרס. הגרסה של קלפטון הגיעה למקום הראשון במצעד האמריקאי, והביאה את שמו של מארלי ואת הרגאיי לקהל גדול בהרבה. בזכותה רבים חיפשו את המקור (אלבום 274). באותה שנה הוא חזר גם להופיע, והלהקה שהקליטה את האלבום ליוותה אותו על הבמה במשך כמה שנים.''',
'''זה אלבום של יום ראשון בבוקר. השוו את I Shot the Sheriff לגרסה המקורית של מארלי, שתגיע בקרוב גם באלבום 323, ותשמעו איך אותו שיר נשמע כששני עולמות נוגעים זה בזה.''',
], [
('I Shot the Sheriff', 'הגרסה הרגועה של שיר של בוב מארלי, ששלחה אותו ואת הרגאיי אל העולם הגדול.'),
('Let It Grow', 'בלדה יפה ומתגברת עם גיטרות אקוסטיות וקולות, מהשירים הטובים שכתב קלפטון.'),
('Motherless Children', 'בלוז ישן בקצב מהיר ומתגלגל, עם גיטרות סלייד, פתיחה מלאת אנרגיה לאלבום רגוע.'),
])

add(306, [
'''קראפטוורק נוסדה בדיסלדורף שבגרמניה על ידי ראלף הוטר ופלוריאן שניידר, שני סטודנטים למוזיקה שחלמו על מוזיקה גרמנית חדשה, לא העתק של רוק אמריקאי. אחרי כמה אלבומים ניסיוניים, ב־1974 הם הוציאו את Autobahn, והפעם השתמשו הרבה בסינתיסייזרים, שהיו אז כלים חדשים ויקרים. יחד עם המפיק קוני פלנק הם בנו עולם של צלילים אלקטרוניים. השם של הלהקה, "תחנת כוח", מתאר את מה שרצו להיות: מוזיקאים שעובדים כמו מהנדסים, עם מכונות וחוטים.''',
'''הצד הראשון כולו הוא יצירה אחת, יותר מעשרים דקות, שמתארת נסיעה בכביש המהיר: רעש מנוע וצופר בפתיחה, קצב מתגלגל ורגוע, מנגינות פשוטות ויפות, וקולות שחוזרים על המשפט "אנחנו נוסעים, נוסעים, נוסעים על האוטובאן". זה נשמע אופטימי, כמעט נאיבי, כמו חלום על מכוניות, כבישים ונוף. בצד השני יש קטעים קצרים ושקטים יותר, על כוכב שביט, על חצות ועל טיול בוקר, עם חליל ופסנתר לצד הסינתיסייזרים. גם המילים פשוטות מאוד, כמעט כמו שיר ילדים: הכביש, הנוף, הרדיו במכונית, והתחושה הנעימה של נסיעה בלי מטרה.''',
'''גרסה מקוצרת של Autobahn הפכה ללהיט באמריקה ובבריטניה, ופתחה לקראפטוורק את הדרך לעולם. מכאן הם הפכו לאבות של המוזיקה האלקטרונית, מהסינת׳־פופ של שנות השמונים ועד הטכנו וההיפ הופ. בסיבוב ההופעות שבא אחרי האלבום הם עמדו על הבמה כמעט בלי לזוז, בחליפות ובתספורות מסודרות, כמו מהנדסים במעבדה.''',
'''שמעו את Autobahn בנסיעה ארוכה, עדיף בלילה. אם אהבתם את המכונות החוזרות של Can (אלבום 277), כאן תשמעו את אותה מחשבה גרמנית, רק נקייה ואלקטרונית.''',
], [
('Autobahn', 'היצירה הגדולה: נסיעה של עשרים דקות בכביש המהיר, עם מנגינות פשוטות וקצב מתגלגל.'),
('Kometenmelodie 2', 'מנגינה אלקטרונית קופצנית על כוכב שביט, שנשמעת כמו משחק וידאו לפני שהיו כאלה.'),
('Morgenspaziergang', 'טיול בוקר: ציוץ ציפורים אלקטרוני, חליל ופסנתר, רגע שקט ופסטורלי בסוף האלבום.'),
])

add(307, [
'''ון מוריסון היה ידוע כזמר ביישן ומסוגר, שלא תמיד נהנה על הבמה. אבל בקיץ 1973 הוא יצא לסיבוב הופעות עם להקה של אחד עשר נגנים, כולל רביעיית כלי קשת וכלי נשיפה, שקרא לה The Caledonia Soul Orchestra. מההופעות בלוס אנג׳לס ובלונדון נבחרו השירים לאלבום כפול, שיצא ב־1974.''',
'''מוריסון שר כאן בלי מעצורים: לוחש, צועק, חוזר על מילה אחת שוב ושוב עד שהיא הופכת לתפילה. יש שירים שלו מאלבומים קודמים, כמו Caravan ו־Into the Mystic מ־Moondance (אלבום 188), ו־Cyprus Avenue מ־Astral Weeks (אלבום 132); יש שירים של אליליו מהסול ומהבלוז, כמו סאם קוק, ריי צ׳ארלס ומאדי ווטרס; ויש גם את Gloria, הלהיט הישן מימי להקת Them. כלי הקשת והנשיפה נותנים לכל שיר רוחב של תזמורת. מוריסון כמעט לא מדבר עם הקהל, אבל הוא מקשיב ללהקה כל הזמן, ולפעמים משנה כיוון באמצע שיר, והנגנים הולכים אחריו.''',
'''רבים מחשיבים אותו לאחד מאלבומי ההופעה הגדולים שנעשו אי פעם. הוא תופס זמר בשיא הכוח שלו, עם להקה שמקשיבה לכל תנועה שלו. בסוף ההופעה מוריסון צועק "It’s too late to stop now!", כבר מאוחר מדי לעצור, ומשם שם האלבום. באותה תקופה הוא כבר היה אמן מוערך מאוד, אבל האלבום הזה הראה לרבים שהקול שלו במיטבו דווקא על הבמה, לא באולפן.''',
'''זה אלבום ארוך, והוא עובד הכי טוב כמו הופעה: ברצף, בערב, בווליום גבוה. אם אין זמן, התחילו בשלושת השירים האחרונים, שהם השיא של הערב.''',
], [
('Caravan', 'השיר מ־Moondance בגרסה ארוכה ושמחה, עם כלי נשיפה והצגת הנגנים באמצע.'),
('Listen to the Lion', 'מוריסון שואג, לוחש וממלמל, בשיא של התמסרות, כאילו הוא מאבד את עצמו בתוך השיר.'),
('Cyprus Avenue', 'הסיום: שיר מ־Astral Weeks שהולך ומתעצם, עד הצעקה האחרונה שנתנה לאלבום את שמו.'),
])

add(308, [
'''אחרי Blue (אלבום 229), ג׳וני מיטשל רצתה לשמוע את שיריה עם להקה. היא עבדה עם נגני ג׳אז צעירים מלוס אנג׳לס, בראשם הסקסופוניסט טום סקוט, ויצרה סאונד חדש: לא עוד זמרת לבד עם גיטרה, אלא פופ חכם עם צבעים של ג׳אז. Court and Spark יצא ב־1974 והפך לאלבום המצליח ביותר שלה.''',
'''השירים עוסקים באהבה ובחופש, ובקושי לשלב בין השניים. Help Me הוא שיר קליל ומתנדנד על התאהבות שאי אפשר לעצור, והיה הלהיט הגדול ביותר שלה. Free Man in Paris נכתב על חבר שלה, איש עסקים גדול בעולם המוזיקה, שחולם על ימים בלי אחריות בפריז. יש כאן גם שירים על מסיבות של אנשים מפורסמים, על נסיעה בלילה ועל בדידות בעיר הגדולה, והקול של מיטשל נע בחופשיות בין גבוה לנמוך. מיטשל עצמה מנגנת בפסנתר ובגיטרה, והנגנים מתאימים את עצמם לאקורדים המיוחדים שלה, שלא דומים לשום דבר אחר בפופ.''',
'''האלבום פתח למיטשל קהל רחב, והגיע למקום השני במצעד האמריקאי. מבקרים רבים רואים בו את החיבור המושלם בין הכתיבה האישית שלה לבין עולם הג׳אז, שאליו היא התקרבה עוד יותר בשנים הבאות. באותה שנה היא יצאה לסיבוב הופעות גדול עם אותה להקה, ואלבום הופעה שיצא אחריו הראה עד כמה הצליל החדש מתאים לה.''',
'''שימו לב לסיום: Twisted הוא שיר ג׳אז ישן ומשעשע על פסיכואנליזה, שמראה צד מצחיק שלה. ואחר כך המשיכו ל־The Hissing of Summer Lawns (אלבום 337), שממשיך מאותה נקודה אל מקום ניסיוני יותר.''',
], [
('Help Me', 'הלהיט הגדול שלה: שיר מתנדנד על אהבה שמפחידה ומושכת בו בזמן.'),
('Free Man in Paris', 'חלום של איש עסקים על חופש מאחריות בפריז, עם גיטרות קלילות וקולות רקע.'),
('Raised on Robbery', 'רוקנרול שובב על אישה בבר, עם גיטרה של רובי רוברטסון מ־The Band.'),
])

add(309, [
'''קווין היו עדיין להקה צעירה כשהקליטו את אלבומם השני, ב־1973: פרדי מרקורי, הגיטריסט בריאן מיי, המתופף רוג׳ר טיילור והבסיסט ג׳ון דיקון. לאלבום, שיצא בתחילת 1974, אין צד א׳ וצד ב׳, אלא "הצד הלבן" ו"הצד השחור". את רוב שירי הצד הלבן כתב בריאן מיי, ואת כל שירי הצד השחור כתב מרקורי. תמונת העטיפה, ארבעתם בחושך עם פנים מוארות, הפכה לאחת התמונות המזוהות עם הלהקה.''',
'''זה אלבום של אגדות, מלכות, מפלצות ופיות. השירים עוברים זה לזה בלי הפסקה, עם שכבות על שכבות של גיטרות וקולות, שהלהקה הקליטה שוב ושוב עד שנשמעו כמו מקהלה שלמה. The March of the Black Queen הוא שיר ארוך ומשתנה, עם קטעי אופרה ורוק, ונחשב לאב הקדמון של Bohemian Rhapsody. Ogre Battle הוא שיר רוק כבד ומהיר על קרב של ענקים. רוי תומס בייקר, המפיק, עזר ללהקה לדחוס לתוך האלבום כמויות עצומות של קולות וגיטרות, ולפעמים נשמע כאילו מנגנות בו עשרות גיטרות יחד.''',
'''האלבום לא מכר כמו אלבומיה המאוחרים של קווין, אבל Seven Seas of Rhye היה הלהיט הראשון שלהם, ומעריצים רבים רואים בו את האלבום הנועז שלהם. כאן נבנה הסגנון שיוביל ל־A Night at the Opera (אלבום 344). The Fairy Feller’s Master-Stroke נכתב בהשראת ציור ויקטוריאני מלא פיות ודמויות זעירות, ומרקורי ביקר בגלריה כדי להתבונן בו.''',
'''שמעו את הצד השחור ברצף, מ־Ogre Battle ועד Seven Seas of Rhye: זה מסע אחד, כמו אופרה קטנה.''',
], [
('The March of the Black Queen', 'שש דקות של אופרה, רוק ושירה בשכבות: הניצן שממנו צמח Bohemian Rhapsody.'),
('Ogre Battle', 'רוק כבד ומהיר על קרב ענקים, עם צעקות, גיטרות סוערות וגונג.'),
('Seven Seas of Rhye', 'הלהיט הראשון של קווין: פסנתר מהיר, גיטרות ושירה מלכותית על ממלכה דמיונית.'),
])

add(310, [
'''Country Life הוא האלבום הרביעי של רוקסי מיוזיק, שיצא בסוף 1974. בריאן אינו (אלבום 300) כבר עזב, ובמקומו הצטרף אדי ג׳ובסון, נגן צעיר של כינור וקלידים. בלי אינו הלהקה פחות מוזרה, אבל חזקה ובטוחה יותר, והזמר בריאן פרי הפך למרכז הבלתי מעורער. שם האלבום לקוח ממגזין אנגלי ותיק על אחוזות כפריות, ובעטיפה המצולמת שתי צעירות בבגדים תחתונים, תמונה שעוררה סערה ובחלק מהחנויות באמריקה הוחלפה בתמונה אחרת.''',
'''המוזיקה מלאה אנרגיה וגלאם: גיטרה מסולסלת של פיל מנזנרה, סקסופון של אנדי מקיי, וכינור חשמלי שנותן צבע חדש. The Thrill of It All פותח בקיר צלילים סוחף, Out of the Blue מתחיל כשיר פופ ונגמר בסולו כינור פרוע, ו־Prairie Rose הוא שיר אהבה אנרגטי לטקסס. פרי שר כמו גבר אלגנטי ומיוסר, מתוך מסיבה שנגמרת מאוחר מדי. גם הפעם יש רגעים שקטים ויפים, כמו A Really Good Time ו־Triptych, שבהם פרי נשמע כמו זמר ממחזמר ישן, מלנכולי ואלגנטי.''',
'''רבים רואים בו את אחד האלבומים הטובים של רוקסי מיוזיק, עם השילוב המדויק בין ניסיוניות לפופ. הוא השפיע על הרבה להקות ניו וויב שבאו אחרי. ג׳ובסון, שהיה אז בן תשע עשרה בלבד, הביא ללהקה אנרגיה חדשה, והכינור החשמלי שלו נשמע כמעט כמו גיטרה נוספת.''',
'''השוו אותו ל־Roxy Music (אלבום 263) ול־For Your Pleasure (אלבום 282), ושימו לב איך הלהקה הפכה ממשהו משונה ומפתיע ללהקת רוק מלוטשת.''',
], [
('The Thrill of It All', 'פתיחה סוחפת, עם קיר של גיטרות, קלידים וכינור, ופרי ששר על ריגוש שלא נגמר.'),
('Out of the Blue', 'שיר פופ שנגמר בסולו כינור חשמלי פרוע של אדי ג׳ובסון, החבר החדש בלהקה.'),
('Prairie Rose', 'שיר אהבה נלהב לטקסס, עם גיטרות סלייד וסקסופון, סיום אנרגטי לאלבום.'),
])

add(311, [
'''טנג׳רין דרים נוסדה בברלין בסוף שנות השישים, ובתחילת שנות השבעים היו בה שלושה חברים: אדגר פרוזה, כריסטופר פרנקה ופטר באומן. Phaedra, שהוקלט בסוף 1973 ויצא ב־1974, היה האלבום הראשון שלהם בחברת התקליטים הבריטית הצעירה וירג׳ין, והפעם הראשונה שבה השתמשו בסיקוונסר: מכשיר שמנגן שוב ושוב רצף של צלילים, כמו לולאה, בזמן שהנגנים משנים את הצבע שלו. השם Phaedra לקוח מהמיתולוגיה היוונית, והוא מתאים לאווירה המסתורית והקדומה של המוזיקה.''',
'''אין כאן שירים ולא מילים. יש ארבעה קטעים ארוכים של צלילים אלקטרוניים: בס פועם שחוזר ומשתנה לאט, שכבות של מלוטרון שנשמעות כמו מקהלה רחוקה, חליל, רעשים ורוח. שיר הנושא נולד בחלקו במקרה: הכלים האלקטרוניים הישנים זזו מהכיוון כשהתחממו, והלהקה החליטה להשאיר את הצלילים המוזרים שנוצרו. התוצאה נשמעת כמו מסע בחלל או מתחת למים, מפחידה ומרגיעה בבת אחת. אין כאן תופים בכלל: הקצב נוצר מהסיקוונסר עצמו, מצלילים שחוזרים שוב ושוב ומשנים לאט את הצבע שלהם.''',
'''בלי שירים ברדיו, האלבום נכנס למצעד הבריטי ומכר היטב, הצלחה מפתיעה למוזיקה כזאת. הרצפים החוזרים שלו השפיעו מאוד על מוזיקה אלקטרונית, מפסקולים של סרטים (הלהקה עצמה כתבה אחר כך הרבה מוזיקה לקולנוע) ועד מוזיקת טראנס ואמביינט. בהופעות של אותן שנים הלהקה אלתרה כמעט הכול, בחושך, מול קהל ששכב על הרצפה והקשיב, לפעמים בכנסיות ובקתדרלות.''',
'''זו מוזיקה להאזנה בחושך, באוזניות, בלי לעשות שום דבר אחר. התחילו בשיר הנושא, שבו אפשר לשמוע בבירור את הסיקוונסר שהפך לסימן ההיכר של הלהקה.''',
], [
('Phaedra', 'יצירה של שבע עשרה דקות: בס אלקטרוני פועם שמשתנה ונע כמו גאות, בין חלום לסיוט.'),
('Mysterious Semblance at the Strand of Nightmares', 'מלוטרון עצוב ורחב של אדגר פרוזה, כמו מקהלה שמזמרת בתוך ערפל.'),
('Sequent C’', 'קטע קצר ושקט של חליל עם הדים, כמו פרידה שקטה בסוף מסע ארוך.'),
])

add(312, [
'''ספארקס הם שני אחים מלוס אנג׳לס, רון וראסל מאל. באמריקה הם כמעט לא הצליחו, אז ב־1973 עברו לאנגליה, חתמו בחברת איילנד ואספו להקה חדשה של נגנים בריטים. האלבום הראשון שהקליטו שם, Kimono My House, יצא ב־1974 והפך אותם בבת אחת לכוכבים.''',
'''הסאונד לא דומה לשום דבר אחר: ראסל שר בקול גבוה ומהיר, כמעט פלסט, שקופץ בין אוקטבות, ורון, שכתב את השירים, מנגן בקלידים בפנים חתומות, בלי חיוך, כמו פקיד. השירים מלאים משחקי מילים, הומור וגלאם רוק מתוזמר, כמו אופרה קטנה שהולחנה בידי מישהו שקרא יותר מדי ספרים. This Town Ain’t Big Enough for Both of Us מלא דרמה של דו־קרב, כולל צלילי יריות, Amateur Hour הוא שיר מהיר על אהבה כתחביב של חובבנים, ו־Here in Heaven מסופר מפי מי שקפץ עם אהובתו מצוק והגיע לגן עדן, רק כדי לגלות שהיא התחרטה ברגע האחרון. הגיטרות חדות והתופים מתפרצים, כמו רוק בריטי קשוח, אבל מעליהם מרחפים הקול והמילים המשונות, והשילוב מצחיק ומרגש בו זמנית.''',
'''This Town Ain’t Big Enough for Both of Us הגיע למקום השני בבריטניה, וההופעה של האחים בטלוויזיה הבריטית נחקקה בזיכרון של דור שלם. ספארקס השפיעו על פופ אלקטרוני ועל להקות רבות שבאו אחריהם, והם ממשיכים להוציא אלבומים עד היום. באותה שנה הם הוציאו אלבום נוסף, והמשיכו להמציא את עצמם מחדש בכל עשור: מגלאם לפופ אלקטרוני, ומשם לאלבומים מתוזמרים.''',
'''הקשיבו למילים: כמעט כל שיר הוא סיפור קצר עם טוויסט. ואם אהבתם את רוקסי מיוזיק (אלבום 263), תשמעו כאן את הצד השובב והמצחיק של אותו גלאם.''',
], [
('This Town Ain’t Big Enough for Both of Us', 'הלהיט: יריות, פסנתר דרמטי ושירה גבוהה ומהירה, כמו דו־קרב במערבון מטורף.'),
('Amateur Hour', 'שיר פופ מהיר ומדבק על אהבה של חובבנים, עם גיטרות חדות והרבה הומור.'),
('Here in Heaven', 'סיפור מפתיע ומצחיק־עצוב מפי אוהב שהגיע לגן עדן לבד, ותוהה מה קרה לה.'),
])

add(313, [
'''סופרטרמפ הוציאו שני אלבומים שלא הצליחו, ואז כמעט התפרקו. שני הכותבים, ריק דייוויס ורוג׳ר הודג׳סון, אספו שלושה נגנים חדשים, ביניהם הסקסופוניסט ג׳ון הליוול, ונסעו לחווה כפרית באנגליה כדי לעבוד על השירים חודשים ארוכים. האלבום השלישי, Crime of the Century, יצא ב־1974 והיה פריצת הדרך שלהם. את השם "סופרטרמפ" הם לקחו מספר של סופר בריטי על נווד, והוא התאים ללהקה שעוד חיפשה את דרכה.''',
'''לשני הכותבים יש קולות שונים מאוד: הודג׳סון שר גבוה ורך, בשירים חלומיים ואופטימיים, ודייוויס שר נמוך ומחוספס, בשירים ציניים וכבדים יותר. יחד נוצר אלבום שמתחבר כמעט לסיפור אחד, על אדם שמרגיש לכוד: בבית הספר, בחברה, בתוך הראש. School פותח במפוחית בודדת ובצלצול של הפסקה, Dreamer הוא שיר פופ קופצני עם פסנתר חשמלי, ו־Crime of the Century סוגר בפסנתר ובתזמורת שהולכים ומתעצמים. Bloody Well Right, שיר עוקצני של דייוויס על בתי הספר ועל המעמדות בבריטניה, הפך ללהיט דווקא ברדיו האמריקאי. הסקסופון של ג׳ון הליוול מוסיף צבע חם ולפעמים עצוב, והפסנתר החשמלי הפך לסימן ההיכר של הלהקה.''',
'''Dreamer נכנס לעשרים הראשונים בבריטניה, והאלבום התקבל כיצירה שלמה ומלוטשת במיוחד. מכאן הדרך הובילה את סופרטרמפ להצלחה גדולה, עד Breakfast in America בסוף העשור. הלהקה ניגנה את האלבום כמעט במלואו בהופעות, והקהל למד את השירים כסיפור אחד, מהצלצול בפתיחה ועד התזמורת בסוף.''',
'''שמעו אותו ברצף ובאוזניות טובות: ההפקה נקייה ומדויקת, ויש בה המון פרטים קטנים, כמו קולות ילדים, הדים וכלי נשיפה, שנכנסים ויוצאים ברגע הנכון.''',
], [
('School', 'הפתיחה: מפוחית בודדת, צלצול בית ספר, וסיפור על מערכת שמכבה את הדמיון.'),
('Dreamer', 'פופ קופצני עם פסנתר חשמלי והקול הגבוה של הודג׳סון, על חולם שלא מוותר.'),
('Crime of the Century', 'סיום גדול: פסנתר, סקסופון ותזמורת שמתרוממים יחד, עד שנשאר רק הד רחוק.'),
])

add(314, [
'''ריצ׳רד תומפסון היה הגיטריסט של פיירפורט קונבנשן (אלבומים 162 ו־169), ועזב את הלהקה כדי לכתוב שירים משלו. ב־1972 הוא התחתן עם הזמרת לינדה פיטרס, וב־1973 הקליטו יחד את האלבום הראשון שלהם כזוג, שיצא ב־1974. הוא כתב את כל השירים וניגן בגיטרה, והיא שרה את רובם, בקול צלול ונקי.''',
'''זה פולק־רוק בריטי, ועם זאת הוא נשמע כמו פאב ישן בעיר עצובה. יש שירים שמחים, כמו שיר הנושא, על מי שעבד כל השבוע ורוצה רק לצאת במוצאי שבת לאורות הבהירים; ויש שירים אפלים מאוד, כמו The End of the Rainbow, שיר ערש לתינוק שאומר לו שאין לו למה לחכות. Withered and Died הוא אחד השירים העצובים והיפים שנכתבו על אכזבה, והגיטרה של ריצ׳רד תומפסון, שנשמעת כמו חמת חלילים או כמו סכין, חותכת בין הבתים. יש גם תזמורת כלי נשיפה, אקורדיון וכלי נשיפה עתיקים, והם מוסיפים צבע אנגלי ישן לשירים חדשים לגמרי.''',
'''האלבום כמעט לא נמכר, אבל עם השנים הוא הפך לאחד האלבומים האהובים של הפולק הבריטי. הזוג המשיך להקליט יחד עד תחילת שנות השמונים, ותומפסון נחשב היום לאחד הכותבים והגיטריסטים הגדולים של אנגליה. רבים רואים בו את אחד האלבומים הטובים ביותר של שנות השבעים באנגליה, למרות שבזמנו כמעט אף אחד לא שמע עליו.''',
'''אל תיבהלו מהעצב: יש כאן גם הומור יבש ואהבה גדולה לשירי עם ישנים. אם אהבתם את Liege & Lief (אלבום 169), תשמעו כאן איך תומפסון לקח את אותה מסורת אל שירים משלו.''',
], [
('I Want to See the Bright Lights Tonight', 'שיר שמח על מוצאי שבת בעיר, עם כלי נשיפה וקצב של פאב, ורצון לשכוח את השבוע.'),
('Withered and Died', 'לינדה שרה שיר עצוב ושקט על חלומות שקמלו, מהיפים שנכתבו בפולק הבריטי.'),
('The Calvary Cross', 'שיר אפל ומהפנט, עם גיטרה חשמלית שבוכה ונושכת, מהשירים האהובים בהופעות של תומפסון.'),
])

add(315, [
'''גיל סקוט־הרון היה משורר וסופר, ובתחילת שנות השבעים גם מוזיקאי שהגיש שירה מדוברת ושירים על החיים של אמריקאים שחורים. השותף הקבוע שלו היה בריאן ג׳קסון, נגן קלידים וחליל. ב־1974 הם הוציאו את Winter in America בחברת תקליטים קטנה ועצמאית של מוזיקאי ג׳אז, אלבום צנוע שנבנה כמעט רק על פסנתר, קלידים חשמליים, חליל וקצב שקט.''',
'''הכותרת, "חורף באמריקה", מתארת תקופה קשה: אחרי רציחת מנהיגים, מלחמת וייטנאם ושערוריית ווטרגייט, כשנראה היה שהתקווה של שנות השישים קפאה. סקוט־הרון שר בקול עמוק וחם, מלא עצב אבל גם עדינות. The Bottle הוא שיר קצבי ומרקיד על אלכוהוליזם בשכונה, שהפך ללהיט במועדונים. Rivers of My Fathers הוא שיר ארוך וכואב על שורשים, ו־Your Daddy Loves You הוא שיר שקט של אב לילדו. ב־H2Ogate Blues הוא מדבר מעל נגינה שקטה על פרשת ווטרגייט, בחוכמה ובהומור. רוב השירים מבוססים על הפסנתר או הפנדר רודס של ג׳קסון, עם בס ותופים עדינים, כך שהמילים תמיד נשמעות בבירור.''',
'''בזכות השילוב של שירה, מילים חדות ומוזיקה שחורה, סקוט־הרון נחשב לאחד מאבות ההיפ הופ, ואמני ראפ רבים דגמו את שיריו. האלבום עצמו נחשב לגולת הכותרת של שיתוף הפעולה עם ג׳קסון. ג׳קסון, שכתב והלחין יחד איתו, נשאר פחות מוכר, אבל רבים אומרים שהצליל החם והמוזיקלי של האלבום הוא במידה רבה שלו.''',
'''הקשיבו למילים, אבל גם לחליל של ג׳קסון, שממלא את החללים ברכות. אם אהבתם את What’s Going On של מרווין גיי (אלבום 207), כאן תשמעו גרסה קטנה, אינטימית וחשופה יותר של אותה שאלה.''',
], [
('The Bottle', 'שיר קצבי ומרקיד עם חליל, על כאבה של שכונה שלמה שבה הבקבוק לוקח אנשים.'),
('Rivers of My Fathers', 'פסנתר ושירה עמוקה על שורשים וגעגוע לבית, שיר ארוך שמתגבר לאט.'),
('Your Daddy Loves You', 'שיר שקט ורך של אב לילדו, שמבטיח אהבה גם בתוך כל הקשיים והמריבות.'),
])

add(316, [
'''בסוף 1974, פחות משנה אחרי Queen II (אלבום 309), קווין הוציאו את אלבומם השלישי. במהלך ההקלטות בריאן מיי חלה קשות ושכב בבית חולים, והלהקה המשיכה לעבוד בלעדיו והשאירה לו מקום להוסיף גיטרות כשיחלים. אולי בגלל זה השירים קצרים וחדים יותר, ומגוונים מאוד.''',
'''זה אלבום של תיבת הפתעות: Brighton Rock נפתח ברעש של יריד ומגיע לסולו גיטרה ארוך, שבו מיי מנגן עם הד שחוזר אחריו ויוצר כמה גיטרות שמנגנות יחד. Killer Queen הוא שיר פופ אלגנטי ושנון על אישה מתוחכמת ומסוכנת, עם פסנתר, מקהלה של קולות ופעמונים. Now I’m Here הוא רוק כבד ומהיר, ו־Stone Cold Crazy מהיר ורועש כל כך שהוא נחשב לאחד הניצנים של הת׳ראש מטאל. וביניהם יש שירים קטנים ומתוקים, כמו Lily of the Valley, ואפילו שיר בסגנון מחזמר ישן. כמו באלבום הקודם, כל ארבעת חברי הלהקה כותבים שירים, ולכן האלבום נשמע כמו אוסף של אישיויות שונות מאוד שמתחברות יחד.''',
'''Killer Queen הגיע למקום השני בבריטניה והיה הלהיט הראשון של קווין באמריקה. האלבום הביא אותם אל קהל גדול, ושם את היסודות להצלחה העצומה של A Night at the Opera (אלבום 344), שיצא שנה אחר כך. מרקורי כתב את Killer Queen כשיר על אישה עשירה ואלגנטית, והשיר מלא שנינות ורמזים, כמו שיר של מחזמר.''',
'''שמעו את Killer Queen פעמיים: פעם בשביל המנגינה, ופעם בשביל כל הפרטים הקטנים, הצלצולים, הגיטרות המוקלטות בשכבות והקולות שעונים זה לזה.''',
], [
('Killer Queen', 'הלהיט הגדול: פופ אלגנטי ושנון עם פסנתר, פעמונים ומקהלת קולות של הלהקה.'),
('Now I’m Here', 'רוק מהיר וקופצני עם הדים וגיטרות, מהשירים שקווין ניגנו כמעט בכל הופעה.'),
('Stone Cold Crazy', 'שתי דקות של רוק מהיר ורועש, הרבה לפני המטאל המהיר, שמטאליקה הקליטו אחר כך.'),
])

add(317, [
'''10cc היו ארבעה מוזיקאים ממנצ׳סטר, שכל אחד מהם יכול היה לכתוב, לשיר, לנגן ולהפיק: אריק סטיוארט, גרהם גולדמן, קווין גודלי ולול קרים. היה להם אולפן משלהם, וזה נתן להם חופש לנסות כל רעיון מטורף. Sheet Music, האלבום השני שלהם, יצא ב־1974.''',
'''כל שיר כאן נשמע כמו מחזמר קטן: מלודיות של הביטלס, הרמוניות קוליות מלוטשות, קצב שמשתנה פתאום, והומור שנון בכל שורה. The Wall Street Shuffle הוא שיר קצבי ולועג על אנשי הכסף בוול סטריט, Silly Love לועג לשירי אהבה מתקתקים, ו־The Worst Band in the World הוא שיר על להקה גרועה שלא אכפת לה. יש גם שיר שמתרחש בהאיטי, שיר על בית מלון בנופש, ושיר שמסופר מפי פצצה שמתקתקת בתוך מטוס. ארבעתם כתבו בזוגות משתנים, ולכל זוג היה סגנון אחר: אחד פופי ומלודי, אחר מוזר ואמנותי, והאלבום מחבר ביניהם בהצלחה.''',
'''The Wall Street Shuffle הגיע לעשרת הראשונים בבריטניה, ושנה אחר כך 10cc הגיעו למקום הראשון עם I’m Not in Love. רבים רואים ב־Sheet Music את האלבום השנון והמגוון ביותר שלהם, וחלק מהטכניקות האולפניות שלהם השפיעו על הפופ הבריטי של השנים הבאות. גודלי וקרים המציאו אחר כך מכשיר שמאפשר לגיטרה לנגן צליל ארוך כמו כינור, והפכו לבמאי קליפים מבוקשים.''',
'''שימו לב כמה פעמים שיר אחד משנה כיוון באמצע. אם אהבתם את השילוב של פופ ושנינות אצל ספארקס (אלבום 312), כאן תשמעו גרסה אנגלית ומוקפדת יותר.''',
], [
('The Wall Street Shuffle', 'שיר קצבי ולועג על אנשי הכסף בוול סטריט, עם גיטרה חדה והרמוניות מבריקות.'),
('Silly Love', 'צחוק על שירי אהבה מתקתקים, עם ריף רוק וקולות שובבים שמתחלפים.'),
('The Worst Band in the World', 'שיר מצחיק ומפתיע על להקה גרועה שדווקא נהנית, ועל תעשיית המוזיקה כולה.'),
])

add(318, [
'''אחרי Harvest (אלבום 245) ניל יאנג היה כוכב ענק, אבל הוא לא רצה להמשיך באותו כיוון. בשנים הבאות מתו מסמים שני חברים קרובים שלו, והוא הקליט שלושה אלבומים אפלים ומחוספסים, שמעריצים קוראים להם "טרילוגיית התעלה". On the Beach, שיצא ב־1974, הוא האמצעי שבהם, והשקט שבהם.''',
'''יש כאן עייפות, עצב ומבט ביקורתי על הצלחה, על פרסום ועל קליפורניה של תחילת שנות השבעים. On the Beach הוא בלוז איטי וחורק על אדם שרוצה להתרחק מהקהל, Revolution Blues הוא שיר רוק מאיים שנשמע כמו מחשבות של כת מסוכנת, ו־Ambulance Blues שסוגר את האלבום הוא שיר ארוך, תשע דקות, עם כינור ומפוחית, מלא זיכרונות וכאב. יאנג שר לפעמים כאילו הוא מדבר לעצמו, והנגינה רפויה, כאילו כולם מאוחר בלילה בחדר אחד. בחלק מהשירים מנגנים חברים מלהקות אחרות, בהם שני חברים מ־The Band, והאווירה רפויה ואינטימית, כמו ערב בין חברים עייפים.''',
'''באותה תקופה האלבום נחשב לכישלון, ובמשך שנים גם לא היה זמין בדיסק. בתחילת שנות האלפיים הוא יצא מחדש ונחשב היום לאחת הפסגות של יאנג, אלבום שחושף אמן שבוחר ללכת נגד הזרם. כמו הרבה מהאלבומים של יאנג, גם זה הוקלט מהר, בלי הרבה תיקונים, כי חשוב לו יותר לתפוס רגע אמיתי מאשר ביצוע מושלם.''',
'''שמעו אותו אחרי Harvest ותרגישו את ההבדל. ובאלבום 340 מחכה Tonight’s the Night, האלבום האפל עוד יותר מאותה תקופה, שדווקא הוקלט לפני On the Beach.''',
], [
('On the Beach', 'בלוז איטי ומהורהר על פרסום ובדידות, עם גיטרה חורקת ושירה עייפה.'),
('Ambulance Blues', 'תשע דקות של כינור, מפוחית וזיכרונות, הסיום הגדול והעצוב של האלבום.'),
('Walk On', 'הפתיחה: שיר רוק רגוע, כמעט אופטימי, על להמשיך הלאה למרות הכול.'),
])

add(319, [
'''ג׳ורג׳ ג׳ונס נחשב בעיני רבים לזמר הקאנטרי הגדול בכל הזמנים: קול עמוק שיכול לעבור בתוך שורה אחת מלחישה לבכי. בתחילת שנות השבעים הוא היה נשוי לזמרת טמי ווינט, ושניהם עבדו עם המפיק בילי שריל, שהביא לנאשוויל כלי קשת, מקהלות והפקה מבריקה. ב־1974, כשהנישואים שלהם כבר התפרקו, יצא The Grand Tour.''',
'''שיר הנושא הוא אחד משירי הקאנטרי העצובים ביותר: הגבר מזמין את המאזין לסיור מודרך בביתו הריק, חדר אחרי חדר, ומראה את הכיסא, את המיטה ואת חדר התינוק, שנשארו אחרי שאשתו עזבה ולקחה את הילד. זה נשמע כמעט כמו מחזה קטן. גם שאר השירים עוסקים בפרידה, בגעגוע ובאהבה שנגמרה, אבל ג׳ונס שר אותם באיפוק, ודווקא בזכות זה הם כואבים כל כך. שריל נהג לבנות את השירים סביב הקול של ג׳ונס, עם פסנתר רך ומקהלה שמרחפת ברקע, כך שכל נשימה של הזמר נשמעת בבירור.''',
'''The Grand Tour הגיע למקום הראשון במצעד הקאנטרי, ורבים מחשיבים אותו לאחד השירים הטובים של ג׳ונס. האלבום הוא דוגמה מושלמת לקאנטרי המלוטש של נאשוויל בשנות השבעים, שבו המיתרים והמקהלות לא מסתירים את הרגש אלא מדגישים אותו. באותן שנים ג׳ונס עצמו היה במשבר קשה, עם שתייה ובעיות אישיות רבות, ורבים שומעים בשירים שלו את הכאב האמיתי שחווה.''',
'''הקשיבו לשיר הנושא בשקט, ועקבו אחרי הסיור בבית. אם אהבתם את הכאב המאופק של האחים לובין (אלבום 3), כאן תשמעו את אותו עצב בלבוש מלא.''',
], [
('The Grand Tour', 'סיור מודרך בבית ריק, חדר אחרי חדר: מהשירים העצובים ביותר בקאנטרי.'),
('Once You’ve Had the Best', 'שיר על אהבה שאי אפשר להחליף, שנכתב בידי ג׳וני פייצ׳ק והפך ללהיט גדול בקאנטרי.'),
('Pass Me By (If You’re Only Passing Through)', 'בקשה שקטה מאישה: אם את רק עוברת, אל תעצרי ואל תשברי לי שוב את הלב.'),
])

add(320, [
'''ג׳ין קלארק היה הכותב הראשי של הבירדס בתחילת דרכם (אלבום 57), אבל עזב את הלהקה כבר ב־1966, בין השאר בגלל פחד מטיסות. מאז הוציא אלבומי סולו יפים, שלא הצליחו. ב־1974 הוא חתם בחברה של דייוויד גפן, ויחד עם המפיק תומס ג׳פרסון קיי יצר אלבום שאפתני ויקר: מקהלות גוספל, נגני אולפן מעולים, ושכבות על שכבות של צלילים.''',
'''No Other הוא אלבום קצר, שמונה שירים בלבד, אבל כל אחד מהם גדול ורחב. יש בו קאנטרי־רוק, גוספל, סול ורוק פסיכדלי, וכולם עטופים בהפקה מלאה ועשירה. Silver Raven הוא שיר מרחף ויפה, Strength of Strings הוא שיר איטי ומיסטי שהולך ומתעצם, ו־Some Misunderstanding הוא שיר ארוך על בלבול וחיפוש, עם קולות נשיים שעולים כמו בכנסייה. הקול של קלארק רך, עייף ומלא חוכמה. לאורך האלבום קלארק שר על אהבה, על אלוהים ועל היקום, במילים מופשטות ופיוטיות יותר מבכל אלבום קודם שלו.''',
'''האלבום נכשל, חברת התקליטים כמעט לא קידמה אותו, והקריירה של קלארק לא התאוששה. אבל עם השנים הוא התגלה מחדש, מוזיקאים צעירים יצאו לסיבוב הופעות מיוחד עם שיריו, והיום רבים רואים בו אוצר אבוד ויצירת המופת של קלארק. יש מי שמכנים אותו "אלבום המופת האבוד" של שנות השבעים, והוא מופיע היום ברשימות של האלבומים הטובים של העשור.''',
'''זה אלבום שכדאי לשמוע כולו, בשקט ובווליום גבוה, כדי לתפוס את כל השכבות. אם אהבתם את הבירדס, שמעו כאן לאן הגיע האיש שכתב להם את השירים היפים ביותר.''',
], [
('Silver Raven', 'שיר מרחף ויפה עם גיטרות ומקהלה, מהרגעים העדינים והמסתוריים של קלארק.'),
('Some Misunderstanding', 'שמונה דקות של גוספל, רוק וחיפוש רוחני, עם קולות נשיים שעולים כמו בכנסייה.'),
('Strength of Strings', 'שיר איטי ומיסטי שנבנה לאט עד שיא, עם תזמור עשיר וקול עייף ומלא חוכמה.'),
])

add(321, [
'''סטילי דן היו בעצם שני אנשים: וולטר בקר ודונלד פייגן, שני חברים מהקולג׳ שאהבו ג׳אז, ספרות והומור שחור, ושכרו סביבם את הנגנים הטובים ביותר שמצאו. Pretzel Logic, האלבום השלישי שלהם, יצא ב־1974, והיה האחרון שבו סטילי דן היו להקה שיוצאת להופעות. מכאן והלאה הם הפכו לפרויקט של אולפן בלבד.''',
'''השירים קצרים, רובם פחות מארבע דקות, אבל כל אחד מהם צפוף ברעיונות: אקורדים של ג׳אז, מלודיות של פופ, ומילים עוקצניות ומסתוריות. Rikki Don’t Lose That Number נפתח במקצב שלקוח משיר ג׳אז מפורסם של הוראס סילבר, והפך ללהיט הגדול ביותר של הלהקה. East St. Louis Toodle-Oo הוא גרסה ליצירה של דיוק אלינגטון משנות העשרים, שבה גיטרה מחקה את החצוצרה המייללת של התזמורת. ו־Parker’s Band הוא מחווה נלהבת לסקסופוניסט צ׳רלי פארקר. המילים מלאות סיפורים קטנים ומשונים: על עיר קטנה, על נסיעה בזמן ועל דמויות מפוקפקות, תמיד עם חיוך קטן וציני.''',
'''האלבום הגיע לעשרת הראשונים באמריקה, ורבים רואים בו את המקום שבו סטילי דן מצאו את עצמם: אהבת הג׳אז שלהם כבר לא הייתה רמז, אלא חלק מהלב של השירים. רבים מנגני הג׳אז העריצו את סטילי דן, ולאורך השנים ניגנו באלבומים שלהם כמה מנגני האולפן הטובים בעולם.''',
'''שמעו אותו אחרי Can’t Buy a Thrill (אלבום 244) ו־Countdown to Ecstasy (אלבום 289), ושימו לב לנגני האולפן: כל סולו כאן הוא מיניאטורה קטנה ומדויקת.''',
], [
('Rikki Don’t Lose That Number', 'הלהיט הגדול: קצב ג׳אזי, מרימבה ופזמון שלא יוצא מהראש, על מספר טלפון שאסור לאבד.'),
('East St. Louis Toodle-Oo', 'מחווה לדיוק אלינגטון, עם גיטרה שמחקה חצוצרה מייללת של תזמורת משנות העשרים.'),
('Any Major Dude Will Tell You', 'שיר ניחומים רך לחבר במצוקה, עם גיטרה אקוסטית יפה והרמוניות חמות.'),
])

add(322, [
'''רנדי ניומן כותב שירים מפי דמויות, ולעתים קרובות דמויות שהוא עצמו לא מסכים איתן. ב־1974 הוא הוציא אלבום שלם על הדרום האמריקאי, שבו גדל בחלק מילדותו: על אנשים פשוטים, על גזענות, על פוליטיקה ועל אסונות טבע. Good Old Boys הוא אולי האלבום השאפתני שלו, ואחד האהובים שבהם. את התזמורת באלבום עיבד ניומן בעצמו, כמו שעשה גם בפסקולים רבים שכתב אחר כך לסרטים.''',
'''Rednecks, שפותח את האלבום, מושר מפי אדם מהדרום שכועס על הליברלים מהצפון שמלגלגים עליו, וטוען שגם בצפון יש גזענות, רק מוסתרת יותר. זה שיר קשה, עם מילים פוגעניות במכוון, והוא עדיין מעורר ויכוח. Louisiana 1927 מספר על השיטפון הגדול של המיסיסיפי, בפסנתר ובתזמורת עדינים ועצובים. Marie הוא שיר אהבה של גבר שיכור, שאומר לאשתו את כל מה שהוא לא מסוגל לומר כשהוא פיכח. ניומן שר בקול עייף ומחויך, ליד פסנתר, עם תזמורת שהוא עצמו עיבד. יש גם שירים שמתארים פוליטיקאים אמיתיים מהדרום, כמו מושל לואיזיאנה ששלט בה ביד רמה, וניומן מתאר אותם בהומור ובחמלה.''',
'''האלבום זכה להערכה רבה, וחלק משיריו חיו חיים משלהם: Louisiana 1927 הפך להמנון אחרי הוריקן קתרינה ב־2005, כשניו אורלינס שוב טבעה במים.''',
'''הקשיבו למילים בזהירות: ניומן כמעט אף פעם לא אומר ישר מה הוא חושב. אם אהבתם את Sail Away (אלבום 240), כאן תשמעו את אותה אירוניה, מכוונת הפעם אל לב אמריקה.''',
], [
('Louisiana 1927', 'שיר עצוב ויפה על השיטפון הגדול של 1927, שחזר להיות אקטואלי אחרי הוריקן קתרינה.'),
('Rednecks', 'שיר נוקב ומטלטל על גזענות בצפון ובדרום, מפי דמות שניומן לא מסכים איתה.'),
('Marie', 'שיר אהבה של שיכור לאשתו: עדין, מביך ונוגע ללב, מהיפים של ניומן.'),
])

add(323, [
'''אחרי Catch a Fire (אלבום 274) ו־Burnin׳, שני חברי הוויילרס הוותיקים, פיטר טוש ובאני ויילר, עזבו את הלהקה. בוב מארלי נשאר לבד בחזית, ובפעם הראשונה האלבום יצא בשם "בוב מארלי והוויילרס". במקום שני הזמרים הוא הביא שלוש זמרות, ביניהן אשתו ריטה, שנקראו I Threes. Natty Dread יצא ב־1974.''',
'''הקצב של הרגאיי רגוע וגמיש, אבל המילים בוערות: על עוני, על רעב, על אלימות המשטרה, ועל אמונת הרסטפארי. Lively Up Yourself פותח בשמחה ובקריאה להתעורר ולרקוד. No Woman, No Cry הוא שיר ניחומים לאישה בשכונת העוני של קינגסטון, עם אורגן חם וזיכרונות מלילות ליד המדורה. Them Belly Full מזכיר שאי אפשר לרקוד כשהבטן ריקה, ו־Rebel Music מספר על מחסום משטרה באמצע הלילה. מפוחית, אורגן וגיטרות בלוז מוסיפים צבעים חדשים לסאונד. הזמרות I Threes עונות למארלי ומלוות אותו כמו מקהלה קטנה, ומוסיפות לשירים רוך וחום.''',
'''באותה שנה הגרסה של אריק קלפטון ל־I Shot the Sheriff (אלבום 305) הפכה את מארלי לשם מוכר, ו־Natty Dread היה הצעד הראשון שלו ככוכב עולמי. גרסת ההופעה של No Woman, No Cry, שהוקלטה שנה אחר כך בלונדון, הפכה לאחד השירים המוכרים בעולם. בשירים רבים מופיעה אמונת הרסטפארי, שרואה באתיופיה ובקיסר היילה סלאסי סמלים של גאולה, והיא נותנת לאלבום עומק רוחני.''',
'''השוו את No Woman, No Cry כאן, איטי ושקט יחסית, לגרסת ההופעה המפורסמת. ושמעו את האלבום בקיץ, בחוץ: זו מוזיקה שנעשתה לשמש.''',
], [
('No Woman, No Cry', 'שיר ניחומים חם, עם אורגן וזיכרונות מלילות ליד המדורה, בגרסת האולפן המקורית.'),
('Lively Up Yourself', 'פתיחה שמחה: קריאה להתעורר, לזוז ולרקוד, עם סקסופון וגיטרה קופצנית.'),
('Rebel Music (3 O’Clock Roadblock)', 'מחסום משטרה בשלוש בלילה, עם מפוחית שבוכה וקצב רגוע ומאיים.'),
])

add(324, [
'''רוברט וויאט היה המתופף והזמר של סופט מאשין (אלבום 193). ביוני 1973, במסיבה בלונדון, הוא נפל מחלון בקומה הרביעית ונותר משותק בפלג גופו התחתון. הוא לא יכול היה לתופף יותר, אבל חלק מהשירים כבר נכתבו לפני התאונה, ובחודשים הארוכים בבית החולים הוא השלים אותם. Rock Bottom, שהפיק ניק מייסון מפינק פלויד, יצא ב־1974.''',
'''זה אלבום שקשה להשוות לכל דבר אחר: קלידים רכים ורועדים, בס עמוק, חצוצרה וגיטרות שנכנסות כמו אורחים, ומעל הכול הקול של וויאט, דק, שביר וילדותי, ששר לפעמים מילים ולפעמים רק הברות. Sea Song, השיר הפותח, הוא שיר אהבה מוזר ויפה לאישה שמשתנה כמו הים. Alifib ו־Alifie הם שיחה אינטימית ומשונה בינו לבין בת זוגו, אלפרדה בנג׳, שגם משתתפת בהקלטה. ובסוף, בשיר האחרון, משורר סקוטי מבוגר קורא טקסט מוזר ומצחיק על רקע כאוס של מוזיקה. הרבה מהנגינה נשמעת כמו אלתור של ג׳אז, אבל היא מדויקת מאוד, ובכל רגע נדמה שהמוזיקה עומדת להתפרק ונשארת שלמה.''',
'''למרות הסיפור הקשה, האלבום לא עצוב במובן הרגיל. הוא עדין, מלא הומור ורוך, ומבקרים רבים רואים בו אחת היצירות החשובות של הרוק האנגלי הניסיוני. וויאט המשיך להקליט עוד עשרות שנים כזמר מיוחד במינו. בזכות האלבום הזה וויאט הפך לדמות אהובה מאוד בעולם המוזיקה הבריטית, ומוזיקאים רבים מכל הסגנונות ציינו אותו כהשראה.''',
'''זה אלבום שדורש שקט: לילה, אוזניות, בלי הפרעות. התחילו ב־Sea Song, ואם הוא נגע בכם, המשיכו עד הסוף.''',
], [
('Sea Song', 'שיר אהבה ימי ומוזר, עם קול שביר ופסנתר חשמלי רועד, מהיפים של וויאט.'),
('Alifib', 'לחישות, נשימות ובס עמוק: שיר אהבה פרטי מאוד לבת הזוג שלו.'),
('Little Red Robin Hood Hit the Road', 'הסיום: גיטרות, חצוצרה ומשורר סקוטי שקורא בקול עמוק טקסט מוזר ומצחיק.'),
])

add(325, [
'''גראם פרסונס עבר דרך הבירדס (אלבום 133) והפלאיינג בוריטו ברדרס (אלבום 140), וחלם על מה שקרא "מוזיקה אמריקאית קוסמית": חיבור בין קאנטרי, סול ורוק. בתחילת שנות השבעים הוא גילה זמרת צעירה בשם אמיילו האריס, והקליט איתה שני אלבומים. בספטמבר 1973, זמן קצר אחרי שסיים את השני, הוא מת ממנת יתר במדבר בקליפורניה, בגיל עשרים ושש. Grievous Angel יצא אחרי מותו, בתחילת 1974.''',
'''זה אלבום קאנטרי חם ועצוב, עם גיטרת סטיל, כינור ופסנתר, ומעל הכול הקולות של פרסונס והאריס, ששרים יחד בהרמוניה כמעט מושלמת. Return of the Grievous Angel פותח בסיפור על מסע ברחבי אמריקה, Love Hurts הוא דואט איטי ושבור לשיר ישן של האחים אוורלי, ו־Brass Buttons הוא שיר עדין על זיכרון של אם שנפטרה. יש גם שירים שמחים, ויש אפילו קטע שמוקלט כאילו בהופעה, עם קהל שהוסף באולפן. כמה מהנגנים הגיעו מהלהקה של אלביס פרסלי, והם נותנים לשירים ליווי מקצועי וחם, שמשאיר את הקולות במרכז.''',
'''האלבום כמעט לא נמכר, אבל השפעתו עצומה: הוא היה אחד הזרעים של הקאנטרי־רוק ושל מה שנקרא היום "אמריקנה". אמיילו האריס המשיכה את הדרך שלו והפכה לכוכבת בעצמה (אלבום 335). בזכות האלבום הזה שמו של פרסונס נשמר, והוא נחשב היום לאחד האבות הגדולים של הקאנטרי־רוק.''',
'''הקשיבו לקולות של שניהם: הם כמעט נוגעים זה בזה בכל שורה. ואם אהבתם את The Gilded Palace of Sin (אלבום 140), שמעו כאן איך פרסונס הגיע לשיא.''',
], [
('Return of the Grievous Angel', 'הפתיחה: מסע ברחבי אמריקה עם שני קולות שמשתלבים, של פרסונס והאריס.'),
('Love Hurts', 'דואט איטי וכואב לשיר של האחים אוורלי, מהדואטים היפים שהוקלטו בקאנטרי.'),
('Brass Buttons', 'שיר עדין ועצוב על זיכרון של אם, עם גיטרת סטיל שבוכה ברקע.'),
])

add(326, [
'''אחרי שני אלבומים של שירי רוק מוזרים ושמחים, כמו Here Come the Warm Jets (אלבום 300), בריאן אינו נכנס לאולפן ב־1975 בלי שירים מוכנים. הוא הביא איתו חפיסת קלפים שיצר עם הצייר פיטר שמידט, שנקראה Oblique Strategies: על כל קלף הוראה מוזרה, כמו "הדגש את הטעויות", שנועדה לשבור מבוי סתום. עם כמה נגנים מעולים, ביניהם רוברט פריפ מקינג קרימזון ופיל קולינס מג׳נסיס, הוא בנה את Another Green World.''',
'''רוב הקטעים כאן הם אינסטרומנטליים וקצרים, כמו תמונות קטנות: קלידים רכים, בס עגול, גיטרות מעובדות, מקצבים עדינים וצלילים שקשה לזהות מאיזה כלי הם באו. רק בחמישה שירים אינו שר, ובהם St. Elmo’s Fire, שבו הגיטרה של פריפ נשמעת כמו ברק, ו־I’ll Come Running, שיר פופ עדין ומתוק. הכול נשמע כמו נוף ירוק ושקט, חלום של מקום שאין במפה. אינו עצמו מנגן בסינתסייזרים, בגיטרה ובכלים שהמציא, ולכל קטע יש מצב רוח משלו: שמח, מסתורי, עצוב או שקט לגמרי.''',
'''האלבום נחשב לגשר בין שירי הרוק של אינו לבין מוזיקת האמביינט שהמציא זמן קצר אחר כך. דרך העבודה שלו באולפן, כמלחין שמשתמש באולפן עצמו ככלי נגינה, השפיעה על דייוויד בואי, על טוקינג הדס ועל דורות של מפיקים.''',
'''זה אלבום לבוקר רגוע או לשעות הערב. אל תחפשו בו שירים, אלא מצב רוח. ושימו לב לשיר הנושא: דקה וחצי בלבד, ועדיין מוכר לרבים כנעימת פתיחה של תוכנית אמנות בטלוויזיה הבריטית.''',
], [
('St. Elmo’s Fire', 'שיר קופצני עם סולו גיטרה של פריפ שנשמע כמו ברק, על אש שמרקדת על תרני ספינות.'),
('The Big Ship', 'קטע אינסטרומנטלי שהולך ומתרחב, כמו ספינה גדולה שמפליגה לאט אל האופק.'),
('I’ll Come Running', 'שיר פופ מתוק ועדין עם פסנתר וגיטרה רכה, מהיפים ששר אינו.'),
])

add(327, [
'''הדיקטייטורס היו חבורת צעירים מניו יורק שאהבו רוקנרול, היאבקות מקצועית, מזון מהיר, טלוויזיה, גלישה ומכוניות, ולא לקחו שום דבר ברצינות. הבסיסט אנדי שרנוף כתב את השירים, והזמר "הנדסום דיק" מניטובה התחיל כאיש צוות של הלהקה, עד שעלה לבמה. Go Girl Crazy! יצא ב־1975, שנה לפני האלבום הראשון של הרמונז. בעטיפה מניטובה מצטלם במדי מתאבק, וזה אומר הכול על הרוח של הלהקה.''',
'''זה רוק מהיר, רועש ומצחיק, עם גיטרות כבדות, צעקות ושורות שנשמעות כמו בדיחות פרטיות של חבר׳ה מהשכונה. The Next Big Thing הוא הכרזה מתרברבת על הלהקה עצמה, Weekend הוא שיר שמח על סוף השבוע, ו־(I Live for) Cars and Girls משלב גיטרות רועשות עם הרמוניות בסגנון הביץ׳ בויז. יש גם גרסאות מטורפות לשירים ישנים, כמו I Got You Babe של סוני ושר. השירה של מניטובה מחוספסת ולא תמיד מדויקת, אבל זה חלק מהעניין: הוא נשמע כמו חבר שעלה לבמה מתוך הקהל.''',
'''האלבום נכשל בזמנו, אבל הוא נחשב היום לאחד האבות של הפאנק האמריקאי: האנרגיה, ההומור, הפשטות והגאווה בתרבות ההמונים, כל מה שהרמונז יעשו זמן קצר אחר כך, כבר נמצא כאן. הלהקה המשיכה להופיע ולהקליט לאורך שנים, ומעריצים של פאנק ושל רוק כבד כאחד רואים בה להקה אהובה.''',
'''אל תחפשו כאן עומק, זו מסיבה. אם אהבתם את הניו יורק דולס (אלבום 299), תשמעו כאן את השלב הבא בדרך לפאנק של ניו יורק.''',
], [
('The Next Big Thing', 'הכרזה מתרברבת וקולנית: הלהקה מציגה את עצמה כדבר הגדול הבא ברוקנרול.'),
('Weekend', 'שיר שמח ורועש על החופש של סוף השבוע, עם הרמוניות ופזמון קליט.'),
('(I Live for) Cars and Girls', 'גיטרות רועשות והרמוניות של גולשים, על מכוניות ובנות, כמו הביץ׳ בויז עם שריון.'),
])

add(328, [
'''נוי! (בגרמנית: "חדש!") היו שני מוזיקאים מדיסלדורף, מיכאל רותר וקלאוס דינגר, ששניהם ניגנו לזמן קצר בקראפטוורק (אלבום 306) לפני שהקימו להקה משלהם. דינגר המציא מקצב תופים פשוט, ישר וקבוע, שמתקדם קדימה בלי סוף, כמו נסיעה בכביש: המבקרים קראו לו "מוטוריק", והוא הפך לאחד הקצבים המשפיעים במוזיקה המודרנית. Neu! ’75 הוא האלבום השלישי שלהם, שהפיק קוני פלנק. דינגר ורותר היו שונים מאוד באופי: דינגר פרוע וקולני, רותר שקט ומעודן, והמתח ביניהם נשמע היטב באלבום.''',
'''לשני הצדדים של האלבום יש אופי שונה לגמרי, כי לשני החברים היו טעמים שונים. הצד הראשון, בהובלת רותר, רגוע ויפה: Isi הוא קטע קצבי ושמח עם פסנתר, ו־Seeland הוא נוף איטי ומהורהר, כמו אגם בערב. בצד השני הצטרפו שני מתופפים, ודינגר שר וצועק: Hero הוא שיר רועש, זועם ומהיר, שנשמע כמו פאנק שנתיים לפני הפאנק. קוני פלנק, המפיק, עזר לחבר בין שני העולמות, והצליל נקי וחם גם ברגעים הרועשים ביותר.''',
'''נוי! כמעט לא הצליחו בזמנם, אבל השפעתם עצומה. דייוויד בואי ובריאן אינו העריצו אותם, ואפשר לשמוע אותם בלהקות אלטרנטיביות ואלקטרוניות רבות עד היום. זה היה האלבום האחרון שלהם לתקופה ארוכה: רותר המשיך לקריירה שקטה ויפה משלו, ודינגר הקים להקה חדשה.''',
'''שמעו את Isi בנסיעה, ואת Hero בווליום גבוה. אם אהבתם את Autobahn (אלבום 306), תשמעו כאן את הצד הפראי יותר של אותה סצנה גרמנית.''',
], [
('Isi', 'קצב מוטוריק שמח עם פסנתר וסינתיסייזר, כמו נסיעה בבוקר בהיר בכביש פתוח.'),
('Hero', 'שיר רועש וזועם עם צעקות ותופים דוהרים: פאנק לפני שהיה פאנק.'),
('Seeland', 'נוף איטי ומהורהר, כמו אגם בשקיעה, עם גיטרה רכה ורעשי רקע.'),
])

add(329, [
'''בתחילת 1974 לד זפלין נסעו לבית כפרי ישן באנגליה, שבו כבר הקליטו בעבר, וכתבו שמונה שירים חדשים. השירים היו ארוכים מדי לאלבום רגיל, אז הם הוסיפו כמה הקלטות שנשארו מהאלבומים הקודמים, והוציאו ב־1975 אלבום כפול. Physical Graffiti היה הראשון בחברת התקליטים של הלהקה עצמה, ועטיפתו מציגה בית דירות בניו יורק שדרך חלונותיו אפשר להציץ פנימה.''',
'''זה אלבום שמראה את כל הפנים של זפלין: בלוז כבד וארוך, כמו In My Time of Dying; פאנק ורוק מקפץ, כמו Trampled Under Foot; שירים אקוסטיים קטנים ויפים; ובלדה עמוקה כמו Ten Years Gone, על אהבה ישנה. ובמרכז עומד Kashmir: ריף אחד שעולה וחוזר, תופים כבדים ואיטיים, ותזמורת של כלי קשת ונשיפה שנשמעת כמו שיירה במדבר. רוברט פלאנט כתב אותו בהשראת נסיעה בדרך מדברית במרוקו. ג׳ון פול ג׳ונס, הבסיסט, מנגן גם בקלידים ומעבד חלק מהשירים, וג׳ון בונהאם מתופף כאן בכוח שאין לו תחליף.''',
'''האלבום הגיע למקום הראשון באמריקה ובבריטניה, ונחשב לאחד השיאים של הלהקה, מעין סיכום של כל מה שידעו לעשות. Kashmir נחשב בעיני חברי הלהקה עצמם לאחד השירים הטובים שלהם. כמה מההקלטות הישנות שנוספו, כמו Bron-Yr-Aur האקוסטי והקצר, מראות את הצד השקט של הלהקה, ונותנות לאלבום נשימה בין הסערות.''',
'''זה אלבום ארוך: שמעו כל פעם צד אחד. אם אהבתם את Led Zeppelin IV (אלבום 224), התחילו ב־Kashmir ואחר כך ב־Ten Years Gone.''',
], [
('Kashmir', 'השיר הגדול: ריף עולה, תופים כבדים ותזמורת, כמו שיירה שמתקדמת במדבר.'),
('In My Time of Dying', 'אחת עשרה דקות של בלוז כבד עם גיטרת סלייד, מבוסס על שיר גוספל ישן.'),
('Ten Years Gone', 'בלדה עמוקה על אהבה ישנה, עם שכבות רבות של גיטרות שמתחברות לתזמורת.'),
])

add(330, [
'''ב־24 בינואר 1975 הגיע הפסנתרן קית׳ ג׳ארט לבית האופרה של קלן, בגרמניה, להופעת סולו בשעה מאוחרת בלילה. הוא היה עייף אחרי נסיעה ארוכה, סבל מכאבי גב ולא ישן. וגרוע מכול: במקום הפסנתר הגדול שביקש, חיכה לו על הבמה פסנתר קטן, מזויף, עם קלידים דביקים וצלילים גבוהים חלשים. הוא כמעט סירב לנגן, אבל המארגנת, נערה בת שבע עשרה, שכנעה אותו. וההקלטה של אותו לילה הפכה לאחד התקליטים הנמכרים בתולדות הג׳אז.''',
'''ג׳ארט אלתר הכול, בלי תווים ובלי תוכנית: יותר משעה של מוזיקה שנולדה ברגע. כדי להתגבר על הפסנתר הגרוע, הוא ניגן בעיקר באמצע המקלדת, והשתמש הרבה במקצבים חוזרים בבס, שמעליהם מלודיות פשוטות ויפות, כמעט כמו שירי עם או גוספל. יש רגעים שקטים ומהורהרים, ויש רגעים שבהם הקצב מתגבר עד שהוא נשמע כמו ריקוד. אפשר לשמוע אותו נושם, רוקע ומזמזם תוך כדי נגינה. ג׳ארט לא תכנן דבר מראש: הוא התחיל מכמה צלילים פשוטים, והקשיב לאן הם לוקחים אותו, כאילו גם הוא שומע את המוזיקה בפעם הראשונה.''',
'''התקליט מכר מיליוני עותקים, והוא אלבום הפסנתר הסולו הנמכר ביותר אי פעם. הוא הביא קהל חדש לג׳אז ולמוזיקה מאולתרת, ופסנתרנים רבים לומדים אותו עד היום. ג׳ארט עצמו לא התלהב מההצלחה של התקליט, וסירב במשך שנים לאפשר לאחרים לנגן אותו בתווים, כי ראה בו רגע אחד שלא חוזר.''',
'''שמעו את החלק הראשון מתחילתו ועד סופו, בלי הפסקה, כמו שהקהל שמע אותו באותו לילה. תנו לדקות הראשונות, השקטות, לקחת אתכם.''',
], [
('Part I', 'כעשרים וחמש דקות של אלתור, שנבנה מכמה צלילים שקטים עד לשיאים גדולים ומרגשים.'),
('Part IIa', 'מקצב חוזר ושמח בבס, כמעט ריקוד, שמתגבר לאט עד שהוא ממלא את כל האולם.'),
('Part IIc', 'הסיום: מנגינה עדינה ופשוטה, כמו שיר ערש, שנשארת בראש עוד זמן רב.'),
])

add(331, [
'''אירוסמית׳ הגיעו מבוסטון, והיו בתחילת דרכם "הרולינג סטונס של אמריקה": הזמר סטיבן טיילר, עם פה גדול וצעקה חדה, והגיטריסט ג׳ו פרי, עם ריפים מחוספסים. שני האלבומים הראשונים שלהם הצליחו רק בינוני. Toys in the Attic, השלישי, יצא ב־1975 עם המפיק ג׳ק דאגלס, והפך אותם לאחת הלהקות הגדולות באמריקה.''',
'''זה רוק קשוח, מחויך ומלא סקס: גיטרות שמשתלבות זו בזו, תופים עם גרוב של פאנק, וטיילר שממטיר מילים מהר כמו ראפר. Walk This Way נבנה על ריף גיטרה קופצני ועל שירה מדוברת ומהירה, Sweet Emotion נפתח בבס שקט ומסתורי לפני שהגיטרות מתפרצות, ושיר הנושא הוא רוקנרול מהיר ופרוע. יש גם בלדה עם תזמורת, You See Me Crying, וגרסה שובבה לשיר ג׳אמפ בלוז ישן משנות החמישים.''',
'''זה האלבום הנמכר ביותר של אירוסמית׳, ו־Sweet Emotion ו־Walk This Way הפכו לשירים הקבועים ברדיו הרוק. אחת עשרה שנים אחר כך, להקת הראפ ראן די.אם.סי הקליטה את Walk This Way יחד עם טיילר ופרי, והגרסה הזאת עזרה לחבר בין הרוק להיפ הופ. אירוסמית׳ המשיכו להצלחה גדולה עוד יותר באלבום הבא, ואחרי משבר ארוך חזרו בשנות השמונים והתשעים והפכו שוב לאחת הלהקות הגדולות בעולם.''',
'''שמעו את Walk This Way ושימו לב לתופים ולשירה המדוברת: כבר כאן יש כמעט ראפ. אם אהבתם את הניו יורק דולס (אלבום 299), תשמעו כאן את אותו רוקנרול פרוע, רק עם כוח של אצטדיון.''',
], [
('Walk This Way', 'ריף קופצני ושירה מהירה כמעט כמו ראפ: הלהיט הנצחי שחזר לחיים עם ראן די.אם.סי.'),
('Sweet Emotion', 'בס מסתורי ושקט שמתפרץ לרוק כבד, מהשירים המוכרים ביותר של הלהקה.'),
('Toys in the Attic', 'שיר הנושא: רוקנרול מהיר, פרוע ורועש, פתיחה של אלבום בלי בלמים.'),
])

add(332, [
'''אחרי זיגי סטארדאסט (אלבום 266) ו־Aladdin Sane (אלבום 272), דייוויד בואי שוב שינה עור. ב־1974 הוא התאהב בסול ובפאנק של שחורים אמריקאים, נסע לפילדלפיה והקליט באולפן Sigma Sound, הבית של "סאונד פילדלפיה", עם נגנים וזמרים של סול. בואי עצמו קרא לתוצאה בחיוך "סול מפלסטיק": בריטי לבן שמנסה לשיר כמו זמר סול, ויודע את זה. בין זמרי הרקע היה לותר ונדרוס, אז צעיר ולא ידוע. בסוף ההקלטות בואי אף הזמין מעריצים צעירים שחיכו מחוץ לאולפן להיכנס ולשמוע את השירים.''',
'''האלבום נשמע חם, רך ומבריק: סקסופון מתפתל, קולות רקע של גוספל, בס עגול וגיטרות פאנקיות. שיר הנושא הוא שיר ארוך ומהיר, מלא מילים, על זוג צעיר באמריקה של אחרי ווטרגייט. Win הוא בלדה איטית ומלטפת, ו־Fame, שבואי כתב יחד עם ג׳ון לנון ועם הגיטריסט קרלוס אלומר, הוא פאנק קר ומינימליסטי על המחיר של הפרסום. לנון ניגן ושר גם בגרסה לשיר של הביטלס, Across the Universe. גם הגיטריסט קרלוס אלומר, שהצטרף כאן לבואי, נשאר איתו שנים ארוכות והפך לאחד השותפים החשובים שלו.''',
'''Fame היה הלהיט הראשון של בואי שהגיע למקום הראשון באמריקה, והאלבום פתח לו את הקהל האמריקאי הגדול. הוא גם הראה שבואי מסוגל לקפוץ בין סגנונות, ולהביא איתו את המעריצים.''',
'''שמעו את Young Americans ואחריו את Station to Station (אלבום 350), שיצא כעבור שנה: תשמעו איך אותו סול חם הופך למשהו קר ואירופי.''',
], [
('Young Americans', 'שיר הנושא: סקסופון, מקהלה ושטף של מילים על זוג צעיר באמריקה של אמצע שנות השבעים.'),
('Fame', 'פאנק קר ומינימליסטי על מחיר הפרסום, שנכתב עם ג׳ון לנון והגיע למקום הראשון באמריקה.'),
('Win', 'בלדת סול איטית ומלטפת עם סקסופון, מהרגעים היפים באלבום.'),
])

add(333, [
'''ברנינג ספיר הוא השם שבו הופיע וינסטון רודני, זמר רגאיי מסנט אן שבג׳מייקה, המחוז שבו נולדו גם בוב מארלי וגם מרקוס גארווי. גארווי היה מנהיג שחור בתחילת המאה העשרים, שקרא לשחורים בכל העולם להתגאות במוצאם ולחזור לאפריקה, ותנועת הרסטפארי רואה בו נביא. ב־1975 הקליט רודני אלבום שלם בהשראתו, עם המפיק ג׳ק רובי ולהקה של נגנים מעולים.''',
'''הקול של רודני עמוק, מתפלל ומהדהד, כמעט כמו חזן. השירים איטיים, כבדים וחוזרניים, עם בס עמוק, תופים חדים, כלי נשיפה נוגים וקולות רקע שעונים לו. Slavery Days שואל שוב ושוב "האם אתם זוכרים את ימי העבדות?", ו־Marcus Garvey מספר על הנביא שנשכח. זו מוזיקה של זיכרון, גאווה ותקווה, שנשמעת כמו טקס. רודני כתב את השירים בעצמו, וניגן אותם עם זמרי ליווי שהשלימו אותו בקריאות ובתשובות, כמו בכנסייה.''',
'''האלבום נחשב לאחד מאלבומי הרוטס רגאיי הגדולים, ולאחד החשובים בסגנון. שנה אחר כך יצאה גרסת דאב שלו, Garvey’s Ghost, שבה הקולות כמעט נעלמים והבס וההדים משתלטים. ברנינג ספיר ממשיך להופיע ולהקליט כבר עשרות שנים. רבים מחשיבים את רודני לאחד הקולות הרוחניים ביותר ברגאיי, והוא נשאר נאמן לאותו מסר לאורך כל הקריירה שלו.''',
'''זו מוזיקה שצריך להתמסר לה, לא לנתח. שמעו אותה בערב, בווליום גבוה, כשהבס ממלא את החדר. ואם אהבתם את Natty Dread (אלבום 323), כאן תשמעו רגאיי אפל ורוחני עוד יותר.''',
], [
('Marcus Garvey', 'שיר הנושא: קריאה חגיגית לזכור את הנביא שנשכח, מעל בס עמוק וכלי נשיפה.'),
('Slavery Days', 'שאלה חוזרת ומהדהדת: האם אתם זוכרים את ימי העבדות? שיר של זיכרון ושל כאב.'),
('Old Marcus Garvey', 'רודני מזכיר את גארווי שוב, ושואל למה אנשים שכחו את מה שלימד.'),
])

add(334, [
'''שני האלבומים הראשונים של ברוס ספרינגסטין קיבלו ביקורות טובות אבל כמעט לא נמכרו, וחברת התקליטים שלו התחילה לאבד סבלנות. Born to Run היה ההזדמנות האחרונה שלו, והוא עבד עליו יותר משנה, בשאפתנות עצומה: הוא רצה שהאלבום יישמע כמו תקליט של פיל ספקטור, עם קיר של צלילים, ויספר את סיפורם של צעירים מניו ג׳רזי שחולמים לברוח. הוא היה אז בן עשרים וחמש, והרגיש שזה הרגע האחרון שלו להוכיח את עצמו.''',
'''כל שיר כאן הוא סרט קטן: לילה, מכוניות, כבישים מהירים, אהבה והבטחה שמחכה אי שם. Thunder Road נפתח בפסנתר ובמפוחית ומזמין בחורה לברוח יחד ברכב, שיר הנושא הוא דהירה מתפרצת של גיטרות, סקסופון ופעמונים, ו־Jungleland, שסוגר את האלבום, הוא אופרה של תשע דקות על לילה בעיר, עם סולו סקסופון ארוך ומפורסם של קלרנס קלמונס. ספרינגסטין שר כאילו חייו תלויים בזה, כי כנראה באמת היו. הנגנים של להקת E Street, ובמיוחד הפסנתרן רוי ביטן והסקסופוניסט קלרנס קלמונס, נותנים לשירים צליל גדול ורחב כמו מסך קולנוע.''',
'''האלבום הפך את ספרינגסטין לכוכב בבת אחת. באותו שבוע תמונתו הופיעה בשערים של שני מגזיני החדשות הגדולים באמריקה, והוא הפך לקול של מעמד הפועלים האמריקאי. העטיפה, שבה ספרינגסטין נשען על כתפו של קלמונס, היא אחת המוכרות ברוק.''',
'''שמעו את האלבום לפי הסדר, כמו לילה אחד שמתחיל בבית ונגמר בעיר. ובמיוחד, תנו ל־Jungleland את תשע הדקות שלו בשקט.''',
], [
('Thunder Road', 'הפתיחה: פסנתר, מפוחית והזמנה לבחורה לעלות לרכב ולברוח יחד מהעיר הקטנה.'),
('Born to Run', 'דהירה של גיטרות, סקסופון ופעמונים: ההמנון של ספרינגסטין ושל כל מי שרוצה לברוח.'),
('Jungleland', 'תשע דקות של לילה בעיר, עם סולו הסקסופון המפורסם של קלרנס קלמונס.'),
])

add(335, [
'''אמיילו האריס הייתה זמרת פולק צעירה כשגראם פרסונס שמע אותה שרה במועדון קטן, והזמין אותה לשיר איתו (אלבום 325). כשפרסונס מת ב־1973, היא נשארה בלעדיו, שבורה, והחליטה להמשיך את המוזיקה שלו. Pieces of the Sky, האלבום הראשון שלה בחברה גדולה, יצא ב־1975. אחרי מותו היא חזרה לוושינגטון, הופיעה בברים קטנים ובנתה לאט את הביטחון להמשיך לבד.''',
'''זה אלבום קאנטרי עדין ויפה, עם גיטרת סטיל, כינור, מנדולינה ופסנתר, ומעל הכול הקול שלה: צלול, גבוה, עם רעד קטן של כאב. רוב השירים הם גרסאות לשירים של אחרים, מדולי פרטון ומרל הגארד ועד שיר של הביטלס, והיא הופכת כל אחד לשלה. Boulder to Birmingham הוא השיר הגדול באלבום, שכתבה בעצמה עם חבר: שיר פרידה כואב מפרסונס, על אובדן ועל הרצון לראות שוב את מי שאיננו. If I Could Only Win Your Love, שיר ישן של האחים לובין, הפך ללהיט ברדיו הקאנטרי. המפיק בריאן אהרן עבד איתה שנים רבות אחר כך, והוא בנה סביבה להקה של נגני קאנטרי מעולים, שנתנו לקול שלה בסיס חם ויציב.''',
'''האלבום פתח לאמיילו האריס קריירה ארוכה ומפוארת, והיא הפכה לאחת הזמרות החשובות של הקאנטרי והאמריקנה, וממשיכה את החזון של פרסונס: קאנטרי ישן ומסורתי, עם לב של רוק.''',
'''שמעו את Boulder to Birmingham מיד אחרי Grievous Angel (אלבום 325): זה ההמשך הטבעי, והפרידה. ואם אהבתם את האחים לובין (אלבום 3), תשמעו כמה היא קרובה אליהם ברוחה.''',
], [
('Boulder to Birmingham', 'שיר פרידה כואב ויפה מגראם פרסונס, שהאריס כתבה והפך לאחד השירים המזוהים איתה.'),
('If I Could Only Win Your Love', 'שיר ישן של האחים לובין, בגרסה רכה ומלאת הרמוניות שהפכה ללהיט.'),
('Coat of Many Colors', 'שיר של דולי פרטון על אמא ענייה שתופרת לבתה מעיל מסמרטוטים צבעוניים.'),
])

add(336, [
'''דיון דימוצ׳י היה כוכב רוקנרול בתחילת שנות השישים, עם להיטים כמו Runaround Sue ו־The Wanderer. אחר כך הוא התמכר, נגמל, והפך לזמר פולק רגוע יותר. ב־1974 הוא נכנס לאולפן עם פיל ספקטור, המפיק האגדי שבנה את "קיר הצליל" של שנות השישים. ההקלטות היו ארוכות, כאוטיות וקשות, ודיון עצמו לא אהב את התוצאה. Born to Be With You יצא ב־1975 רק בבריטניה, וכמעט לא נמכר.''',
'''זה אלבום איטי, כבד וחלומי. ספקטור עוטף כל שיר בשכבות עבות של כלים: כמה פסנתרים וגיטרות, תופים עם הדים ענקיים, כלי קשת, מקהלות. בתוך כל זה דיון שר בקול עייף, עמוק ורך, כמו אדם שחזר ממקום רחוק. שיר הנושא הוא גרסה איטית מאוד לשיר פופ משנות החמישים, שהופך כאן לתפילה. Only You Know ו־In and Out of the Shadows, שכתב ספקטור עם גרי גופין, נשמעים כמו חלום שנמשך לאט. גם בשירים שכתב דיון עצמו, כמו Your Own Back Yard, על ההתמודדות שלו עם ההתמכרות, יש כנות שקטה ומפתיעה.''',
'''במשך שנים האלבום היה כמעט סוד, אבל מוזיקאים כמו פיט טאונשנד ובובי גילספי מפרימל סקרים הרבו לשבח אותו, ובהדרגה הוא זכה להכרה כיצירה אבודה ומיוחדת, אחת האחרונות של ספקטור. רק שנים רבות אחר כך האלבום יצא מחדש ונעשה זמין לקהל רחב, והוא מופיע היום ברשימות של האלבומים הנשכחים הגדולים.''',
'''זו לא מוזיקה לרקע. הקשיבו באוזניות ותנו לשכבות להיפתח: בכל האזנה תשמעו כלי נוסף שמסתתר בתוך הקיר.''',
], [
('Born to Be with You', 'שיר פופ ישן משנות החמישים שהפך לתפילה איטית, עמוקה ועטופה בקיר של צלילים.'),
('Only You Know', 'קיר צליל חלומי וקול עייף ורך, שיר של ספקטור וגופין שנשמע כמו חלום.'),
('In and Out of the Shadows', 'שיר איטי ועצוב, כמו הליכה בין אור לצל, עם מקהלה ופסנתרים רבים.'),
])

add(337, [
'''אחרי ההצלחה של Court and Spark (אלבום 308), ג׳וני מיטשל יכלה לחזור על הנוסחה. היא בחרה בדיוק בהפך: The Hissing of Summer Lawns, שיצא ב־1975, נועז, ג׳אזי ומורכב יותר. במקום שירים אישיים על הלב שלה, היא כתבה סיפורים על אחרים: על נשים עשירות בפרברים של לוס אנג׳לס, בבתים עם בריכות ומדשאות שמשקים אותן בקיץ, וכלואות בתוך חיים מבריקים וריקים.''',
'''המוזיקה עשירה, עם נגני ג׳אז, מקהלות קוליות ומנגינות מפתיעות. In France They Kiss on Main Street פותח בשמחה, בזיכרון של נעורים וריקודים. The Jungle Line נבנה על הקלטה של מתופפים מבורונדי שבאפריקה, עם סינתיסייזר, הרבה לפני שזה היה מקובל. Edith and the Kingpin הוא סיפור איטי ומסתורי על אישה ועל איש כוח מסוכן, ו־Shadows and Light שסוגר את האלבום נשמע כמו מקהלה של כנסייה. שם האלבום מתאר את הצליל של ממטרות על מדשאות הפרברים בערב קיץ, ומיטשל משתמשת בו כסמל לחיים שנראים מושלמים מבחוץ.''',
'''בזמנו מבקרים רבים לא הבינו את האלבום והתאכזבו ממנו. היום הוא נחשב לאחת היצירות הטובות שלה, ואמנים רבים, ביניהם פרינס, סיפרו כמה הוא השפיע עליהם. מיטשל המשיכה בשנים הבאות להתקרב לג׳אז, ועבדה עם כמה מגדולי נגני הג׳אז של התקופה.''',
'''זה אלבום שנפתח לאט. שמעו אותו כמה פעמים, והקשיבו למילים כאילו הן סיפורים קצרים. אם אתם מכירים רק את Blue (אלבום 229), תופתעו לשמוע עד כמה מיטשל הרחיקה.''',
], [
('In France They Kiss on Main Street', 'פתיחה קלילה ושמחה על נעורים, ריקודים ורוקנרול, זיכרון של ימים פשוטים יותר.'),
('The Jungle Line', 'תופים מאפריקה וסינתיסייזר: ניסוי נועז ומרתק, הרבה לפני שזה היה מקובל.'),
('Edith and the Kingpin', 'סיפור איטי ומסתורי על אישה צעירה ועל איש כוח מסוכן בעיר קטנה.'),
])

add(338, [
'''טום ווייטס היה בן עשרים וחמש כשהקליט את האלבום הזה, אבל כבר נשמע כמו איש לילה ותיק: קול צרוד, בדיחות של ברמן, וסיפורים על דיינרים, מלצריות, נהגי משאיות ושיכורים. ב־1975 הוא הפך את האולפן בלוס אנג׳לס למועדון לילה, עם שולחנות, משקאות וקהל קטן של מוזמנים, והקליט מול הקהל, יחד עם רביעיית ג׳אז, אלבום כפול שחציו מוזיקה וחציו סטנדאפ.''',
'''בין השירים ווייטס מדבר: מספר סיפורים, ממציא מילים, משחק עם הקהל בהומור יבש ומהיר. והשירים עצמם הם ג׳אז לילי ועייף, עם בס עומד, סקסופון ופסנתר. Eggs and Sausage הוא שיר על ארוחה במסעדה פתוחה כל הלילה, Warm Beer and Cold Women הוא שיר בודד ושיכור, ו־Big Joe and Phantom 309 הוא סיפור רפאים על נהג משאית שעוזר לטרמפיסט. שם האלבום לקוח מציור מפורסם של אדוארד הופר, שבו כמה אנשים בודדים יושבים בלילה בדיינר מואר. הקהל באולפן צוחק, מגיב ומוחא כפיים, ונשמע כמו קהל של מועדון אמיתי, כך שקל לשכוח שזה בעצם אולפן הקלטות.''',
'''האלבום לא היה להיט, אבל הוא בנה את הדמות של ווייטס: המשורר של האנשים שחיים בשולי העיר, בלילה. מכאן הוא המשיך לדרך ארוכה ומגוונת, מהשירים העדינים ועד המוזיקה הניסיונית של שנות השמונים. ווייטס רצה להביא לתקליט את האווירה של המועדונים הקטנים שבהם הופיע, ואת ההומור שהקהל שם אהב.''',
'''שמעו את האלבום מאוחר בלילה, כמו שהוא נועד. אל תדלגו על הדיבורים: הם חלק מההופעה, ולעתים קרובות מצחיקים יותר מכל שיר.''',
], [
('Eggs and Sausage (In a Cadillac with Susan Michelson)', 'ארוחה בדיינר באמצע הלילה, עם פסנתר וסקסופון עייפים וסיפור על אנשים בודדים.'),
('Warm Beer and Cold Women', 'שיר בודד ושיכור על בירה פושרת ונשים קרות, מהיפים של ווייטס.'),
('Big Joe and Phantom 309', 'סיפור רפאים על נהג משאית, בקול של מספר סיפורים ליד מדורה.'),
])

add(339, [
'''ראהול דב בורמן, שכונה בפשטות "פנצ׳ם", היה אחד המלחינים הגדולים של בוליווד, תעשיית הקולנוע של הודו. הוא היה בנו של מלחין מפורסם, ומגיל צעיר אהב לערבב: מוזיקה הודית עם ג׳אז, רוק, פאנק, מוזיקה לטינית וכל צליל חדש שהגיע מהמערב. Shalimar היה סרט שוד הודי־אמריקאי משנת 1978, עם כוכבים הודים לצד שחקן בריטי מפורסם. הסרט נכשל, אבל הפסקול שלו חי עד היום.''',
'''הפסקול מערבב שירים ומוזיקה אינסטרומנטלית של מתח, ונשמע כמו סרט ריגול של שנות השבעים שהוקלט בבומביי: כלי נשיפה חדים, גיטרות פאנק, בס קופצני, קלידים אלקטרוניים ומקצבי דיסקו, לצד כלים הודיים. Hum Bewafa Hargiz Na Thay, בביצועו של קישור קומאר, הוא שיר אהבה עצוב ויפה שהפך לקלאסיקה בהודו, ו־One Two Cha Cha Cha, בביצועה של אושה אות׳ופ, הוא שיר מסיבה עליז ומשוגע. ויש קטעי מוזיקה מהסרט עצמו, מסתוריים וקצביים, שמזכירים פסקולים של סרטי ג׳יימס בונד. בורמן עצמו היה ידוע גם בשירה המחוספסת והמשונה שלו, ובניסויים עם כלים וחפצים מכל הסוגים כדי להשיג צליל חדש.''',
'''הפסקולים של בורמן היו אהובים בהודו, אבל במערב גילו אותם באיחור: תקליטנים ומפיקי היפ הופ התחילו לחפש את התקליטים שלו ולדגום אותם. הבחירה בפסקול הזה לספר היא הזדמנות לשמוע עולם שלם של מוזיקה פופולרית הודית.''',
'''אל תחפשו כאן אלבום אחיד, אלא מסע בזמן לקולנוע ההודי של שנות השבעים. אם אהבתם את הגרוב של Bongo Rock (אלבום 271), תשמעו כאן פאנק מכיוון אחר לגמרי.''',
], [
('Hum Bewafa Hargiz Na Thay', 'שיר אהבה עצוב של קישור קומאר, שנפתח בקטע דיבור מהסרט והפך לקלאסיקה בהודו.'),
('One Two Cha Cha Cha', 'שיר מסיבה עליז ומשוגע של אושה אות׳ופ, עם קצב לטיני וכלי נשיפה.'),
('Mera Pyar Shalimar', 'שיר אהבה בקולה של אשה בוסלה, עם תזמור עשיר ומלודיה מתגלגלת.'),
])

add(340, [
'''בסוף 1972 מת מסמים דני ויטן, הגיטריסט של קרייזי הורס, הלהקה של ניל יאנג (אלבום 135). כעבור כמה חודשים מת גם ברוס בארי, איש צוות של הלהקה. בקיץ 1973 אסף יאנג כמה חברים, נכנס לאולפן בלוס אנג׳לס, והקליט בשעות הלילה, אחרי שתייה, שירים על המתים ועל החיים שנמשכים אחריהם. חברת התקליטים נבהלה, והאלבום נגנז לשנתיים. הוא יצא רק ב־1975, אחרי On the Beach (אלבום 318).''',
'''זה אחד האלבומים המחוספסים שיצאו מאמן גדול: השירה מזייפת לפעמים, הקול נשבר, הנגינה רופפת, ולפעמים נשמע כאילו מישהו עומד להירדם. אבל דווקא זה מה שעושה אותו אמיתי. שיר הנושא, שחוזר בפתיחה ובסיום, מספר על ברוס בארי ועל הלילה שבו מת. Tired Eyes מספר, כמעט בדיבור, על עסקת סמים שנגמרה ברצח. ובאמצע יש הקלטת הופעה ישנה שבה שר דני ויטן עצמו. נילס לופגרן ובן קית׳ היו שותפים שהבינו את מצב הרוח, והנגינה שלהם עדינה ועצובה, בלי שום ניסיון לייפות.''',
'''בזמנו רבים לא ידעו מה לעשות עם אלבום כל כך עצוב ומבולגן. היום הוא נחשב לאחד האלבומים הטובים של יאנג, ולאחת היצירות הכנות ביותר על אבל ועל התמכרות. יאנג עצמו הגן תמיד על האלבום, דווקא בגלל שהוא לא מלוטש.''',
'''שמעו אותו מאוחר בלילה, אחרי On the Beach, ואל תצפו לשלמות. ואם אהבתם את Everybody Knows This Is Nowhere (אלבום 135), שבו ויטן עוד מנגן, תבינו מה נאבד.''',
], [
('Tonight’s the Night', 'שיר הנושא: אבל, צעקה ופסנתר חורק על חבר שמת, שחוזר גם בסוף האלבום.'),
('Tired Eyes', 'שיר כמעט מדובר ועצוב על עסקת סמים שנגמרה ברצח, ועל עיניים עייפות.'),
('Albuquerque', 'שיר שקט ועייף על בריחה ממקומות ומאנשים, עם גיטרת סטיל עדינה.'),
])

add(341, [
'''באמצע שנות השבעים בוב דילן היה כבר אגדה, אבל שנים ארוכות לא הוציא אלבום שהתקרב לגדולת שנות השישים שלו (אלבומים 36, 50, 58 ו־64). ב־1974 הנישואים שלו התפרקו, והוא כתב סדרת שירים על אהבה, פרידה, כעס וגעגוע. דילן עצמו הכחיש שהשירים מספרים על חייו, אבל רוב המאזינים שמעו בהם בדיוק את זה. את האלבום הקליט בניו יורק, ואז, כמה שבועות לפני יציאתו, הקליט מחדש חצי מהשירים במיניאפוליס, עם נגנים מקומיים שכמעט לא הכיר.''',
'''הנגינה פשוטה ושקטה: גיטרה אקוסטית, בס, אורגן, מפוחית. אבל השירים עמוקים מאוד. Tangled Up in Blue קופץ בין זמנים, מקומות וגופים, כמו רומן שלם בשבע דקות. Idiot Wind הוא שיר זועם ומריר, מהכועסים שדילן כתב, ו־If You See Her, Say Hello הוא שיר פרידה רך ועצוב. Shelter from the Storm מספר על אישה שנתנה לו מחסה מהסערה, וכמעט נשמע כמו תפילה. גם הנגינה כאן אינטימית במיוחד: הגיטרה של דילן מכוונת בכיוונון פתוח, והלהקה נשמעת כאילו היא מנסה לא להפריע לו.''',
'''האלבום הגיע למקום הראשון באמריקה, ורבים רואים בו את אחד משני או שלושה האלבומים הטובים ביותר של דילן, ואחד מאלבומי הפרידה הגדולים שנכתבו אי פעם. בשנים שאחר כך יצאו גם ההקלטות המקוריות מניו יורק, ומעריצים רבים אוהבים להשוות בין שתי הגרסאות.''',
'''הקשיבו למילים, ואל תנסו לפענח הכול. שמעו את Tangled Up in Blue פעמיים, ושימו לב איך הסיפור משנה את נקודת המבט שלו באמצע, כמו זיכרון שמתעקש לחזור בגרסאות שונות.''',
], [
('Tangled Up in Blue', 'רומן שלם בשבע דקות: זמנים, מקומות ונקודות מבט מתערבבים בסיפור אהבה.'),
('Idiot Wind', 'שיר זועם ומריר, עם אורגן ומפוחית, מהכועסים ביותר שדילן כתב.'),
('Shelter from the Storm', 'שיר שקט ורך, כמעט תפילה, על אישה שנתנה לו מחסה מהסערה.'),
])

add(342, [
'''פטי סמית׳ הגיעה מניו ג׳רזי לניו יורק בסוף שנות השישים, רזה, ענייה ומלאת חלומות, וכתבה שירה. בתחילת שנות השבעים היא התחילה לקרוא את שיריה עם גיטרה ברקע, ומשם נולדה להקה. ב־1975, בזמן שסצנת המועדון CBGB הייתה בחיתוליה, היא הקליטה את Horses, עם המפיק ג׳ון קייל מהוולווט אנדרגראונד (אלבום 91). את תמונת העטיפה, שחור־לבן פשוט ומפורסם, צילם חברה הקרוב רוברט מייפלת׳ורפ.''',
'''זה רוקנרול שמתערבב עם שירה: פטי סמית׳ שרה, מדברת, צועקת ולוחשת, והלהקה מלווה אותה כמו להקת ג׳אז שמגיבה לכל מילה. האלבום נפתח ב־Gloria, השיר הישן של ון מוריסון מתקופת Them (אלבום 307), שמתחיל בשורה פרובוקטיבית משלה ומתפרץ לריקוד פרוע. Birdland הוא שיר ארוך ומאולתר על ילד שמחכה לאביו המת שיבוא לקחת אותו בחללית, ו־Land הוא מסע של תשע דקות בין חלום, סוסים וריקוד. הגיטריסט לני קיי, שהיה גם חוקר ואספן של תקליטי רוק ישנים, נתן ללהקה את הבסיס של רוקנרול פשוט ומחוספס.''',
'''Horses נחשב לאחד האלבומים החשובים של הפאנק, עוד לפני שהמילה הזאת הייתה נפוצה, ולהשראה עצומה לנשים ברוק. הוא הראה שאפשר לחבר רוקנרול פשוט ומלוכלך עם שירה ואמנות גבוהה. פטי סמית׳ המשיכה לכתוב ספרים, שירה וזיכרונות, וזכתה בפרסים ספרותיים, והיא נחשבת היום לאחת האמניות המשפיעות של דורה.''',
'''שמעו את האלבום ברצף, ואל תיבהלו מהקטעים הארוכים: הם הלב שלו. אם אהבתם את הוולווט אנדרגראונד, תשמעו כאן את ההמשך הישיר שלהם.''',
], [
('Gloria', 'השיר של ון מוריסון, שהפך אצלה להכרזה פרועה ומשחררת עם שורת פתיחה משלה.'),
('Land', 'תשע דקות של שירה, רוק וריקוד, מסע בין חלום למציאות.'),
('Free Money', 'שיר שמתחיל שקט ומתפרץ, על חלום לזכות בלוטו ולקנות הכול לאמא.'),
])

add(343, [
'''אחרי The Dark Side of the Moon (אלבום 291), פינק פלויד היו מהלהקות הגדולות בעולם, אבל גם עייפים, תקועים ורחוקים זה מזה. מתוך התחושה הזאת נולד Wish You Were Here, שיצא ב־1975: אלבום על היעדרות. על חברים שכבר אינם באמת שם, על תעשיית המוזיקה שהופכת אמנים למכונות, ובעיקר על סיד בארט, המייסד של הלהקה (אלבום 89), שעזב אותה ב־1968 כשמצבו הנפשי התדרדר.''',
'''האלבום נפתח ונסגר ב־Shine On You Crazy Diamond, יצירה ארוכה לכבוד בארט: קלידים ארוכים ושקטים, ואז ארבעה צלילי גיטרה של דייוויד גילמור שנעשו מפורסמים כמו מנגינה. Welcome to the Machine הוא קטע אלקטרוני קר ומאיים, Have a Cigar לועג למנהלי חברות התקליטים, ושיר הנושא הוא שיר אקוסטי פשוט ועצוב, מהאהובים של הלהקה. באחד מימי ההקלטות הופיע באולפן אדם שמן, מגולח ראש וגבות, וחברי הלהקה לא זיהו אותו: זה היה סיד בארט עצמו.''',
'''האלבום הגיע למקום הראשון בבריטניה ובאמריקה, ושניים מחברי הלהקה, גילמור והקלידן ריצ׳רד רייט, אמרו שזה האלבום האהוב עליהם מכל מה שעשו. עטיפת האלבום, שני אנשי עסקים לוחצים ידיים כשאחד מהם עולה באש, היא אחת המוכרות ברוק. רבים מהמעריצים רואים בו את האלבום האישי והרגשי ביותר של הלהקה, דווקא כי הוא נולד מתוך עייפות, ריחוק וגעגוע.''',
'''שמעו את האלבום ברצף, בחושך, ורצוי באוזניות: הצלילים עוברים בין הצדדים ומתמזגים מקטע לקטע. ושימו לב לרגע שבו שיר הנושא נפתח, כאילו מתוך רדיו ישן.''',
], [
('Shine On You Crazy Diamond (Parts I-V)', 'הפתיחה הגדולה: קלידים ארוכים וארבעה צלילי גיטרה מפורסמים, מחווה לסיד בארט.'),
('Wish You Were Here', 'שיר אקוסטי פשוט ועצוב על געגוע, שנפתח כאילו מתוך רדיו ישן.'),
('Welcome to the Machine', 'אלקטרוני, קר ומאיים: ברוכים הבאים לתעשייה שהופכת אמנים למכונות.'),
])

add(344, [
'''ב־1975 קווין היו על סף פשיטת רגל, למרות ההצלחה של Sheer Heart Attack (אלבום 316): חוזה גרוע עם המנהלים הקודמים השאיר אותם כמעט בלי כסף. הם עברו להנהלה חדשה, ונכנסו לאולפן עם שאיפה אחת: לעשות את האלבום הגדול ביותר שיכלו. A Night at the Opera, שנקרא על שם סרט של האחים מרקס, היה אחד האלבומים היקרים שהוקלטו עד אז.''',
'''זה אלבום של כל הסגנונות יחד: רוק כבד, בלדות, שירי מחזמר ישנים, פולק ואפילו המנון. Death on Two Legs הוא שיר זועם שכוון אל המנהל הקודם, You’re My Best Friend של הבסיסט ג׳ון דיקון הוא שיר פופ חם ושמח, ו־’39 של בריאן מיי הוא שיר פולק על אסטרונאוטים שחוזרים מהחלל וגילו שעברו מאה שנה. ובמרכז, Bohemian Rhapsody: שש דקות של בלדה, אופרה ורוק כבד, בלי פזמון, עם עשרות קולות מוקלטים זה על זה. מרקורי, מיי, טיילור ודיקון כתבו כולם שירים לאלבום, וכל אחד מהם הביא סגנון משלו, כך שהאלבום נשמע כמו תוכנית ערב מגוונת.''',
'''כולם אמרו שהשיר ארוך מדי לרדיו, אבל Bohemian Rhapsody היה תשעה שבועות במקום הראשון בבריטניה, והסרטון שצולם לו נחשב לאחד מראשוני הקליפים. האלבום הפך את קווין לאחת הלהקות הגדולות בעולם. עד היום הוא אחד האלבומים האהובים של קווין, והשירים שלו הפכו לחלק מהזיכרון המוזיקלי של דורות שלמים.''',
'''שמעו את האלבום ברצף, ושימו לב כמה הוא מגוון. ואחרי Bohemian Rhapsody, תנו הזדמנות לשירים הפחות מוכרים, כמו ’39 ו־Love of My Life.''',
], [
('Bohemian Rhapsody', 'שש דקות של בלדה, אופרה ורוק כבד, מהשירים המפורסמים בעולם.'),
('’39', 'שיר פולק של בריאן מיי על אסטרונאוטים שחוזרים אחרי מאה שנה לעולם שהשתנה.'),
('You’re My Best Friend', 'שיר פופ חם ושמח של הבסיסט ג׳ון דיקון, עם פסנתר חשמלי והרמוניות.'),
])

add(345, [
'''וילי נלסון כתב שירים מצליחים לאחרים, כמו Crazy של פטסי קליין, אבל כזמר הוא לא הצליח בנאשוויל, שם רצו שיישמע מלוטש. בתחילת שנות השבעים הוא עבר לאוסטין שבטקסס, גידל שיער וזקן, והפך לאחד מאנשי "הקאנטרי של הפורעים", שעשו מוזיקה בדרכם. ב־1975 הוא חתם בחברה גדולה עם חופש אמנותי מלא, והקליט באולפן קטן בטקסס, במהירות ובזול, את Red Headed Stranger.''',
'''זה אלבום קונספט, שמספר סיפור מהמערב הפרוע: כומר שאשתו עזבה אותו בשביל אחר, והוא הורג את שניהם ויוצא לנדוד על סוסו, עד שהוא מוצא אהבה חדשה. הנגינה חשופה מאוד: הגיטרה המרופטת של נלסון, פסנתר של אחותו בובי, קצת מפוחית ובס, והקול הרך והקצבי שלו, שמדבר כמעט יותר משהוא שר. השירים קצרים, חלקם קטעי מעבר של דקה, והכול זורם כמו סיפור לפני השינה. נלסון שר את הסיפור בשקט, כמעט בלי קישוטים, והמקצב הרגוע של הגיטרה שלו מזכיר סוס שהולך לאט בדרך ארוכה.''',
'''כששמעו את האלבום, אנשי חברת התקליטים חשבו שזו הקלטה ביתית, לא אלבום גמור. אבל Blue Eyes Crying in the Rain, שיר ישן משנות הארבעים, הפך ללהיט הראשון של נלסון כזמר, והאלבום הפך אותו לכוכב גדול. היום הוא נחשב לאחד האלבומים החשובים בתולדות הקאנטרי.''',
'''שמעו אותו כמו שמאזינים לסיפור: ברצף ובשקט. אם אהבתם את Will the Circle Be Unbroken (אלבום 254), כאן תשמעו קאנטרי פשוט באותה מידה, אבל אפל ואישי יותר.''',
], [
('Blue Eyes Crying in the Rain', 'שיר ישן משנות הארבעים, גיטרה אחת וקול רך: הלהיט הגדול שהפך את נלסון לכוכב.'),
('Time of the Preacher', 'הפתיחה: הסיפור על הכומר שליבו נשבר, וחוזר כמו נושא לאורך האלבום.'),
('Hands on the Wheel', 'שיר עדין על מציאת שלווה בסוף הדרך, אחרי כל הנדודים.'),
])

add(346, [
'''מוריס ווייט היה מתופף אולפן בשיקגו, שחלם על להקה שתאחד סול, פאנק, ג׳אז, מוזיקה אפריקאית ומיסטיקה. כך נוסדה ארת׳, ווינד אנד פייר: להקה גדולה, עם כלי נשיפה, כלי הקשה, ושני זמרים, ווייט עצמו ופיליפ ביילי, שהקול הגבוה שלו, בפלסט, נשמע כמעט כמו כלי נגינה. ב־1975 הם כתבו מוזיקה לסרט על תעשיית התקליטים, That’s the Way of the World. הסרט נכשל, אבל האלבום הגיע למקום הראשון באמריקה.''',
'''זה אלבום של אופטימיות: קצב שמח, כלי נשיפה מבריקים, קולות מלאים בהרמוניה, והרבה תקווה. Shining Star הוא שיר פאנק קצבי שאומר לכל אחד שיש בו כוכב שזורח, ושיר הנושא הוא שיר רך ומתגלגל על האמת שבתוך כולנו. Reasons הוא בלדה שבה ביילי עולה לגבהים מדהימים בקול שלו. ובאמצע נשמעת קלימבה, כלי אפריקאי קטן שמוריס ווייט אהב. Africano הוא קטע אינסטרומנטלי סוער של כלי נשיפה ותופים, שמזכיר שהלהקה באה גם מהג׳אז. הצליל נבנה סביב כלי הנשיפה המבריקים, שהפכו לסימן ההיכר של הלהקה, ומוריס ווייט עצמו מנגן גם בקלימבה.''',
'''Shining Star הגיע למקום הראשון במצעד האמריקאי, והלהקה הפכה לאחת הגדולות של שנות השבעים. אחר כך יבואו Boogie Wonderland ו־September. בהופעות של הלהקה היו קסמים, פירמידות ובמות מסתובבות, ומוריס ווייט רצה שהמוזיקה תעורר השראה ותחושה של התעלות.''',
'''שמעו את האלבום בבוקר, כשצריך אנרגיה. ושימו לב ל־Reasons: הקול של ביילי נשמע כמו כלי נגינה.''',
], [
('Shining Star', 'פאנק קצבי ושמח שהגיע למקום הראשון: יש בכל אחד כוכב שזורח.'),
('That’s the Way of the World', 'שיר רך ומתגלגל על אמת ועל אהבה, מהיפים של הלהקה.'),
('Reasons', 'בלדה שבה פיליפ ביילי מגיע לגבהים מדהימים בקול הפלסט שלו.'),
])

add(347, [
'''אחרי ההצלחה של Superfly (אלבום 246), קרטיס מייפילד הוציא ב־1975 אלבום שקט ורציני הרבה יותר. העטיפה מבוססת על צילום מפורסם משנות השלושים: תור של אנשים שחורים שנפגעו משיטפון, שמחכים לעזרה, מתחת לשלט ענק שמציג משפחה לבנה מחייכת במכונית, עם הכיתוב "רמת החיים הגבוהה בעולם". שם האלבום, "אין מקום כמו אמריקה היום", הוא אירוניה מרה.''',
'''יש כאן רק שבעה שירים, רובם איטיים ושקטים: פאנק רך, כמעט מינימליסטי, עם בס, תופים, גיטרה עדינה והקול הגבוה והרך של מייפילד, שנשמע עייף ועצוב. Billy Jack מספר על צעיר שנורה, Hard Times מתאר חיים של קושי ועוני, ו־Blue Monday People מדבר על אנשים עובדים שמחכים לסוף השבוע. ויש גם אהבה ותקווה: So in Love הוא שיר אהבה חם, ו־Jesus הוא תפילה שקטה. מייפילד כתב, שר, ניגן בגיטרה והפיק בעצמו, והצליל החשוף מדגיש את המילים ומשאיר מקום לשקט.''',
'''האלבום לא מכר כמו Superfly, אבל היום רבים רואים בו את אחת היצירות החשובות של מייפילד: מבט כן וכואב על אמריקה, שאין בו צעקות אלא אמת שקטה. מייפילד המשיך לכתוב ולהקליט גם אחרי שנפצע קשה בתאונה על במה ב־1990 ונותר משותק, ואף הקליט אלבום אחרון בשכיבה.''',
'''הקשיבו לו בשקט, בלילה. אם אהבתם את What’s Going On (אלבום 207) ואת Winter in America (אלבום 315), תשמעו כאן את אותה דאגה לאמריקה, בקול שקט עוד יותר.''',
], [
('Billy Jack', 'שיר איטי ומאיים על צעיר שנורה, עם כלי נשיפה נוגים ובס עמוק.'),
('So in Love', 'שיר אהבה חם ורך, רגע של אור ותקווה באלבום רציני.'),
('Hard Times', 'פאנק איטי ועמוק על חיים של קושי, בקולו הרך של מייפילד.'),
])

add(348, [
'''טום פטי גדל בגיינסוויל שבפלורידה, ובתחילת שנות השבעים נסע עם הלהקה שלו ללוס אנג׳לס כדי לנסות את מזלו. הלהקה התפרקה, אבל פטי אסף כמה מחבריה ונגנים נוספים מאותה עיר, והקים את הרטברייקרס. אלבום הבכורה שלהם יצא בסוף 1976, בזמן שהפאנק והדיסקו שלטו, והוא נשמע אחרת: רוקנרול פשוט, ישר וכן, שאוהב את הבירדס (אלבום 57), את הרולינג סטונס ואת בוב דילן. חלק מהחברים בלהקה הכירו עוד מימי הנעורים בגיינסוויל, וזה נשמע: הם מנגנים יחד בטבעיות של חברים ותיקים.''',
'''השירים קצרים וחדים, עם גיטרות מצלצלות, אורגן והקול המחוספס, המאונפף קלות, של פטי. Breakdown הוא שיר איטי, מסתורי וסקסי, עם ריף גיטרה שקט ומפתה. American Girl, שסוגר את האלבום, הוא שיר מהיר עם גיטרת שתים עשרה מיתרים שמזכירה את הבירדס, על בחורה שחולמת על חיים אחרים, והפך לאחד השירים הגדולים בתולדות הרוק האמריקאי. ובין לבין יש את Rockin’ Around (With You), פתיחה מהירה ושמחה, ואת Luna, שיר איטי וחלומי עם אורגן. הקלידן בנמונט טנץ׳ והגיטריסט מייק קמפבל ליוו את פטי כמעט בכל הקריירה, וכבר כאן אפשר לשמוע כמה הם מבינים זה את זה.''',
'''בהתחלה האלבום כמעט לא נמכר באמריקה, דווקא בבריטניה הקהל התלהב ראשון, ורק אחר כך אמריקה גילתה אותם. פטי והרטברייקרס הפכו לאחת הלהקות האהובות באמריקה, עם קריירה של ארבעים שנה, עד מותו של פטי ב־2017.''',
'''התחילו ב־American Girl, אחר כך שמעו את האלבום מההתחלה: זה אלבום קצר, בלי מילוי, וכל שיר עושה את שלו.''',
], [
('American Girl', 'גיטרת שתים עשרה מיתרים, קצב דוהר ובחורה שחולמת על חיים אחרים.'),
('Breakdown', 'שיר איטי ומסתורי עם ריף גיטרה מפתה, הלהיט הראשון של הלהקה באמריקה.'),
('Anything That’s Rock ’n’ Roll', 'רוקנרול שמח ופשוט, שהצליח ראשון דווקא בבריטניה.'),
])

add(349, [
'''ג׳ונתן ריצ׳מן היה נער מבוסטון שהעריץ את הוולווט אנדרגראונד (אלבום 91) עד כדי כך שנסע לניו יורק כדי להיות קרוב אליהם. בתחילת שנות השבעים הוא הקים להקה, המודרן לאברס, עם נגנים שעוד יתפרסמו בלהקות אחרות: הקלידן ג׳רי הריסון, שיצטרף אחר כך לטוקינג הדס, והמתופף דייוויד רובינסון, שיצטרף לדה קארס. ב־1972 ג׳ון קייל מהוולווט הפיק להם הקלטות, אבל הלהקה התפרקה לפני שיצא תקליט. ההקלטות יצאו רק ב־1976, כאלבום.''',
'''זה רוקנרול פשוט מאוד, עם שני אקורדים, אורגן זמזמני וגיטרה חורקת, אבל עם מילים שלא דומות לשום דבר אחר. Roadrunner הוא שיר על נסיעה בלילה בכביש מהיר ליד בוסטון, עם הרדיו פתוח, מתוך אהבה עצומה לעולם המודרני: לכבישים, לחנויות, לאורות. Pablo Picasso מספר בחיוך מרושע על הצייר שהצליח עם כל הבנות, ו־Hospital הוא שיר אהבה עדין ומביך לבחורה בבית חולים. ריצ׳מן שר כמו ילד תמים וכן, בלי שום ניסיון להיראות מגניב. הצליל פשוט מאוד, כמעט מינימליסטי, והאורגן הזמזמני של ג׳רי הריסון חוזר על אותו רעיון שוב ושוב, בדיוק כמו אצל הוולווט אנדרגראונד.''',
'''כשהאלבום יצא, ריצ׳מן כבר עבר לשירים אקוסטיים שקטים וילדותיים, אבל ההקלטות האלה הפכו לאחד מאבות הפאנק. הסקס פיסטולס הקליטו את Roadrunner, ודייוויד בואי וג׳ון קייל הקליטו את Pablo Picasso. המעטים ששמעו את הלהקה בהופעות בבוסטון בתחילת שנות השבעים סיפרו אחר כך שלא היה לה שום דבר דומה באותו זמן.''',
'''שמעו את Roadrunner בנסיעה, בלילה, עם החלונות פתוחים: זה בדיוק מה שהשיר אומר לעשות.''',
], [
('Roadrunner', 'שני אקורדים, נסיעה בלילה עם הרדיו פתוח והתאהבות בעולם המודרני.'),
('Pablo Picasso', 'שיר מרושע ומצחיק על הצייר שהצליח עם כל הבנות, עם אורגן מזמזם.'),
('Hospital', 'שיר אהבה עדין ומביך לבחורה בבית חולים, מהכנים שנכתבו.'),
])

add(350, [
'''ב־1975 דייוויד בואי גר בלוס אנג׳לס, והייתה זו התקופה החשוכה בחייו: הוא היה מכור לקוקאין, רזה מאוד, כמעט לא ישן, ואמר אחר כך שהוא כמעט לא זוכר את הקלטת האלבום. הוא המציא דמות חדשה, "הדוכס הלבן הרזה", אריסטוקרט קר ומנוכר בחליפה לבנה. Station to Station יצא בתחילת 1976, ויש בו רק שישה שירים, אבל כל אחד מהם הוא עולם.''',
'''האלבום מחבר בין הסול והפאנק של Young Americans (אלבום 332) לבין משהו חדש, אירופי ומכני, בהשפעת להקות גרמניות כמו קראפטוורק (אלבום 306). שיר הנושא נפתח ברעש של רכבת שעוברת בין הרמקולים, מתקדם לאט ובכבדות, ואז מתפרץ לפאנק רוקד. Golden Years הוא שיר פופ מתוק ומרקיד, Word on a Wing היא תפילה אמיתית של אדם אבוד, ו־Wild Is the Wind, גרסה לשיר ישן שנינה סימון שרה, סוגר את האלבום בשירה מדהימה של בואי. הגיטריסט קרלוס אלומר והבסיסט ג׳ורג׳ מארי נותנים לאלבום גרוב פאנקי חזק, ומעליהם בואי שר בקול גבוה, רחוק ומנוכר.''',
'''רבים רואים בו את אחד האלבומים הטובים של בואי: גשר בין הסול האמריקאי לבין "טרילוגיית ברלין" שהקליט אחר כך עם בריאן אינו, שבה הלך עוד יותר לכיוון האלקטרוני והניסיוני. בסיבוב ההופעות שאחרי האלבום בואי הופיע על במה חשופה, באור לבן חזק, ומראה הדוכס הלבן הרזה הפך לאחד המפורסמים שלו.''',
'''שמעו את שיר הנושא עד הסוף, עשר דקות, ותנו לרכבת להגיע. ואחרי Wild Is the Wind, תבינו למה רבים אומרים שבואי שר כאן טוב מתמיד.''',
], [
('Station to Station', 'עשר דקות: רכבת שעוברת בין הרמקולים, מסע איטי וכבד, ואז פאנק רוקד.'),
('Golden Years', 'שיר פופ מתוק ומרקיד עם כפיים וקולות, מהלהיטים הגדולים של בואי.'),
('Wild Is the Wind', 'הסיום: שיר ישן שנינה סימון שרה, בשירה מדהימה ומלאת רגש של בואי.'),
])
